'use client';
import Logo from "@/components/common/Logo";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { zodResolver } from "@hookform/resolvers/zod";
import { ArrowLeft, ArrowRight, Loader, Loader2 } from "lucide-react";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import * as z from "zod";
import { motion } from "motion/react";
import { useSignUpMutation } from "@/lib/feature/auth/authApi";
import { UserRegistrationBase } from "@/types/auth";

const signupSchema = z.object({
    firstName: z.string().min(2, "First name is too short"),
    lastName: z.string().min(2, "Last name is too short"),
    email: z.string().email("Invalid email address"),
    grade: z.string().optional(),
    password: z.string().min(8, "Password must be at least 8 characters"),
    confirmPassword: z.string().min(8, "Password must be at least 8 characters"),
}).refine((data) => data.password === data.confirmPassword, {
    message: "Passwords don't match",
    path: ["confirmPassword"],
});

type SignupSchema = z.infer<typeof signupSchema>;

export default function SignupPage() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const inviteHash = (searchParams.get("invite") || "").replace(/\/+$/, "");
    const roleParam = searchParams.get("role") || "";
    const isTeacher = roleParam.toUpperCase().includes("TEACHER") || inviteHash.toUpperCase().includes("TEACHER");

    const [signUp, { isLoading }] = useSignUpMutation()

    const {
        register,
        handleSubmit,
        formState: { errors },
    } = useForm<SignupSchema>({
        resolver: zodResolver(signupSchema),
        defaultValues: {
            firstName: "",
            lastName: "",
            grade: "",
            email: "",
            password: "",
            confirmPassword: "",
        }
    });

    const onSubmit = async (formData: SignupSchema) => {
        try {
            const payload: UserRegistrationBase = {
                firstName: formData.firstName,
                lastName: formData.lastName,
                email: formData.email,
                password: formData.password,
            };

            if (isTeacher) {
                payload.token = inviteHash;
            } else {
                // Map "grade-9" to "Grade 9"
                const gradeValue = formData.grade?.split('-').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
                payload.gradeLevel = gradeValue;
            }

            const response = await signUp(payload).unwrap();
            toast.success(response.message || "Account created successfully!");
            router.push("/login");
        } catch (error: any) {
            const errorMessage = error?.data?.message || "Something went wrong. Please try again.";
            toast.error(errorMessage);
        }
    };

    return (
        <main className="min-h-screen bg-background flex flex-col p-6">
            <Logo />
            <div className="flex flex-1 items-center justify-center px-6.5 pb-7">
                <motion.div
                    initial={{ opacity: 0, y: 40 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.5, ease: "easeOut" }}
                    className="w-full max-w-lg translate-y-0 md:-translate-y-12">
                    <div className="bg-card border rounded-2xl p-6 sm:p-7 md:p-8 shadow-[0_4px_4px_0] shadow-primary/20">

                        <button onClick={() => router.back()} className="text-foreground hover:text-primary/80 mb-5 flex items-center gap-2 cursor-pointer">
                            <ArrowLeft size={20} />
                        </button>

                        <h2 className="text-xl sm:text-2xl md:text-3xl font-bold text-text-strong mb-2">
                            Set up Your Account
                        </h2>

                        <p className="text-stroke-weak text-sm mb-6 sm:mb-7 md:mb-8">
                            Get started by creating your account in just simple steps.
                        </p>

                        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4 sm:space-y-5">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-text-strong text-sm font-medium mb-2.5">First Name</label>
                                    <Input {...register("firstName")} placeholder="Scott" className={`bg-background text-text-strong placeholder:text-stroke-weak rounded-[10px] h-12 ${errors.firstName ? "border-red-500 focus-visible:ring-red-500" : "focus-visible:ring-primary"}`} />
                                    {errors.firstName && <p className="text-red-500 text-xs mt-1.5 ml-1">{errors.firstName.message}</p>}
                                </div>
                                <div>
                                    <label className="block text-text-strong text-sm font-medium mb-2.5">Last Name</label>
                                    <Input {...register("lastName")} placeholder="Friedman" className={`bg-background text-text-strong placeholder:text-stroke-weak rounded-[10px] h-12 ${errors.lastName ? "border-red-500 focus-visible:ring-red-500" : "focus-visible:ring-primary"}`} />
                                    {errors.lastName && <p className="text-red-500 text-xs mt-1.5 ml-1">{errors.lastName.message}</p>}
                                </div>
                            </div>

                            <div>
                                <label className="block text-text-strong text-sm font-medium mb-2.5">Email</label>
                                <Input type="email" {...register("email")} placeholder="example@mail.com" className={`bg-background text-text-strong placeholder:text-stroke-weak rounded-[10px] h-12 ${errors.email ? "border-red-500 focus-visible:ring-red-500" : "focus-visible:ring-primary"}`} />
                                {errors.email && <p className="text-red-500 text-xs mt-1.5 ml-1">{errors.email.message}</p>}
                            </div>

                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-text-strong text-sm font-medium mb-2.5">Password</label>
                                    <Input {...register("password")} type="password" placeholder="••••••••" className={`bg-background text-text-strong placeholder:text-stroke-weak rounded-[10px] h-12 ${errors.password ? "border-red-500 focus-visible:ring-red-500" : "focus-visible:ring-primary"}`} />
                                    {errors.password && <p className="text-red-500 text-xs mt-1.5 ml-1">{errors.password.message}</p>}
                                </div>
                                <div>
                                    <label className="block text-text-strong text-sm font-medium mb-2.5">Confirm Password</label>
                                    <Input {...register("confirmPassword")} type="password" placeholder="••••••••" className={`bg-background text-text-strong placeholder:text-stroke-weak rounded-[10px] h-12 ${errors.confirmPassword ? "border-red-500 focus-visible:ring-red-500" : "focus-visible:ring-primary"}`} />
                                    {errors.confirmPassword && <p className="text-red-500 text-xs mt-1.5 ml-1">{errors.confirmPassword.message}</p>}
                                </div>
                            </div>
                            
                            {!isTeacher && (
                                <div>
                                    <label className="block text-text-strong text-sm font-medium mb-2.5">Select Grade</label>
                                    <div className="relative">
                                        <select
                                            {...register("grade")}
                                            className={`w-full bg-background text-text-strong rounded-[10px] h-12 px-3 pr-10 focus:outline-none focus:ring-2 appearance-none cursor-pointer transition-all border ${errors.grade
                                                ? "border-red-500 focus:ring-red-500"
                                                : "border-primary/50 focus:border-primary focus:ring-primary/20"
                                                }`}
                                        >
                                            <option value="" className="text-stroke-weak">Select your grade</option>
                                            <option value="grade-9">Grade 9</option>
                                            <option value="grade-10">Grade 10</option>
                                            <option value="grade-11">Grade 11</option>
                                            <option value="grade-12">Grade 12</option>
                                        </select>
                                        <div className="pointer-events-none absolute inset-y-0 right-3 flex items-center">
                                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5 text-primary">
                                                <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
                                            </svg>
                                        </div>
                                    </div>
                                    {errors.grade && <p className="text-red-500 text-xs mt-1.5 ml-1">{errors.grade.message}</p>}
                                </div>
                            )}

                            <Button
                                disabled={isLoading}
                                type="submit"
                                className="w-full bg-primary hover:bg-primary/90 text-muted font-semibold rounded-2xl h-12 text-base mt-5 cursor-pointer"
                            >
                                {isLoading ? (
                                    <>
                                        <Loader className="mr-2 h-5 w-5 animate-spin" />
                                        Creating Account...
                                    </>
                                ) : (
                                    <>
                                        Create Account
                                        <motion.span
                                            animate={{ x: [0, 5, 0] }}
                                            transition={{ repeat: Infinity, duration: 1.5 }}
                                        >
                                            <ArrowRight size={28} strokeWidth={2.5} className="ml-2" />
                                        </motion.span>
                                    </>
                                )}
                            </Button>
                        </form>

                        <p className="text-muted-foreground text-sm mt-6 text-center">
                            Already you have an account?{" "}
                            <Link href="/login" className="text-primary font-medium underline">Log In</Link>
                        </p>
                    </div>
                </motion.div>
            </div>
        </main>
    );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter, useParams } from "next/navigation";
import { Calendar, Clock, User, Bell, Trash2, Loader2, ArrowRight } from "lucide-react";
import { DatePicker } from "@/components/ui/date-picker";
import { TimePicker } from "@/components/ui/time-picker";
import { format, parse } from "date-fns";
import { useGetCourseByIdQuery, useUpdateCourseMutation, useGetTeachersQuery, useRemoveTeacherMutation } from "@/lib/feature/courses/coursesApi";
import { toast } from "sonner";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { CustomSwitch } from "@/components/ui/custom-switch";

export default function PublishCoursePage() {
    const router = useRouter();
    const params = useParams();
    const courseId = params?.id as string;

    const { data: courseRes, isLoading: isCourseLoading } = useGetCourseByIdQuery(courseId, { skip: !courseId });
    const [updateCourse, { isLoading: isUpdating }] = useUpdateCourseMutation();
    const { data: teachersRes } = useGetTeachersQuery();
    const [removeTeacher, { isLoading: isRemovingTeacher }] = useRemoveTeacherMutation();

    const course = courseRes?.data;
    const teachers = teachersRes?.data || [];

    const [mounted, setMounted] = useState(false);
    const [isFinalizing, setIsFinalizing] = useState(false);

    // Form state
    const [startDate, setStartDate] = useState("");
    const [startTime, setStartTime] = useState("09:00 AM");
    const [endTime, setEndTime] = useState("11:00 AM");
    const [selectedTeacherId, setSelectedTeacherId] = useState<string | null>(null);
    const [notificationsEnabled, setNotificationsEnabled] = useState(true);

    useEffect(() => {
        setMounted(true);
        if (course) {
            if (course.startDate) setStartDate(format(new Date(course.startDate), "yyyy-MM-dd"));
            if (course.startTime) setStartTime(course.startTime);
            if (course.endTime) setEndTime(course.endTime);
            if (course.teacherId) setSelectedTeacherId(course.teacherId);
        }
    }, [course]);

    const handleRemoveTeacher = async () => {
        setSelectedTeacherId(null);
        if (!courseId) return;
        try {
            await removeTeacher(courseId).unwrap();
            toast.success("Teacher removed from course");
        } catch (err: any) {
            // Error handling
        }
    };

    const handlePublishCourse = async () => {
        if (!courseId) return;

        setIsFinalizing(true);
        try {
            const updatePayload = {
                id: courseId,
                isPublished: true, // we publish it!
                startDate: startDate ? new Date(startDate).toISOString() : new Date().toISOString(),
                startTime: startTime,
                endTime: endTime,
                teacherId: selectedTeacherId || undefined
            };

            await updateCourse(updatePayload).unwrap();
            toast.success("Course published successfully!");
            router.push("/admin/courses");
        } catch (err: any) {
            toast.error(err?.data?.message || "Failed to publish course. Please try again.");
        } finally {
            setIsFinalizing(false);
        }
    };

    if (isCourseLoading || !mounted) {
        return (
            <div className="min-h-screen text-white flex items-center justify-center">
                <Loader2 className="w-12 h-12 text-[#D4AF37] animate-spin" />
            </div>
        );
    }

    if (!course) {
        return (
            <div className="min-h-screen text-white flex items-center justify-center">
                <div className="text-center">
                    <h2 className="text-xl font-bold mb-2">Course not found</h2>
                    <button onClick={() => router.push('/admin/courses')} className="text-[#D0AD6B] underline">Go back</button>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen text-white pb-8 transition-opacity duration-500 opacity-100">
            <div>
                {/* Header Section */}
                <div className="bg-[#0a0a0a] border border-gray-800 rounded-xl p-8 mb-6 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-[#D0AD6B]/5 blur-3xl rounded-full -mr-32 -mt-32" />
                    <h1 className="text-white text-2xl font-bold mb-2">PUBLISH COURSE</h1>
                    <p className="text-gray-400 text-sm">Finalize settings and make {course.courseName || course.subject} available to students</p>
                </div>

                {/* Course Start Date */}
                <div className="bg-[#121212] border border-gray-800 rounded-2xl p-7 mb-6 hover:border-[#D0AD6B]/40 hover:shadow-2xl hover:shadow-[#D0AD6B]/5 transition-all duration-500 group relative overflow-hidden hover:-translate-y-1">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-[#D0AD6B]/5 blur-3xl rounded-full -mr-16 -mt-16 group-hover:bg-[#D0AD6B]/10 transition-colors duration-500" />
                    <div className="flex items-center gap-3 mb-6 relative z-10">
                        <div className="p-2.5 bg-[#D0AD6B]/10 rounded-xl group-hover:scale-110 group-hover:bg-[#D0AD6B]/20 transition-all duration-300">
                            <Calendar className="w-4 h-4 text-[#D0AD6B]" />
                        </div>
                        <div>
                            <h2 className="text-[#D0AD6B] text-[10px] font-black uppercase">Course Start Date</h2>
                            <p className="text-gray-500 text-[10px] font-medium tracking-tight">Select when students can begin</p>
                        </div>
                    </div>
                    <div className="relative z-10">
                        <DatePicker
                            date={startDate ? parse(startDate, "yyyy-MM-dd", new Date()) : undefined}
                            setDate={(d) => setStartDate(d ? format(d, "yyyy-MM-dd") : "")}
                            placeholder="Select starting date..."
                        />
                    </div>
                </div>

                {/* Course Schedule */}
                <div className="bg-[#0a0a0a] border border-gray-800 rounded-xl p-8 mb-6 relative hover:border-[#D0AD6B]/30 transition-all">
                    <div className="flex items-center gap-2 mb-6">
                        <Clock className="w-4 h-4 text-[#D0AD6B]" />
                        <h2 className="text-[#D0AD6B] text-xs font-bold uppercase tracking-wider">COURSE SCHEDULE</h2>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="relative">
                            <TimePicker value={startTime} onChange={setStartTime} placeholder="09:00 AM" />
                        </div>
                        <div className="relative">
                            <TimePicker value={endTime} onChange={setEndTime} placeholder="11:00 AM" />
                        </div>
                    </div>
                    <p className="text-gray-500 text-[10px] mt-4 ml-1">Students will gain access to course materials on this time</p>
                </div>

                {/* Assign Teacher */}
                <div className="bg-[#0a0a0a] border border-gray-800 rounded-xl p-8 mb-6 hover:border-[#D0AD6B]/30 transition-all">
                    <div className="flex items-center gap-2 mb-4">
                        <User className="w-4 h-4 text-[#D0AD6B]" />
                        <h2 className="text-[#D0AD6B] text-xs font-bold uppercase tracking-wider">ASSIGN TEACHER</h2>
                    </div>

                    {!selectedTeacherId ? (
                        <div className="space-y-4">
                            <Select onValueChange={setSelectedTeacherId} value={selectedTeacherId || ""}>
                                <SelectTrigger className="w-full bg-[#111] border-gray-800 text-gray-300 focus:ring-[#D0AD6B]/20 focus:border-[#D0AD6B] h-12">
                                    <SelectValue placeholder="Search teacher..." />
                                </SelectTrigger>
                                <SelectContent className="bg-[#111] border-gray-800 text-gray-300">
                                    {teachers.map((t: any) => (
                                        <SelectItem key={t.id} value={t.id} className="hover:bg-primary/10 focus:bg-primary/10">
                                            <div className="flex items-center gap-2 py-1">
                                                <div className="w-8 h-8 rounded-full overflow-hidden bg-[#D0AD6B]/10 border border-[#D0AD6B]/20 flex items-center justify-center">
                                                    {t.avatar ? (
                                                        <img src={t.avatar} alt="" className="w-full h-full object-cover" />
                                                    ) : (
                                                        <span className="text-xs font-bold text-[#D0AD6B] uppercase">{t.name?.[0] || t.email?.[0] || "T"}</span>
                                                    )}
                                                </div>
                                                <div className="flex flex-col">
                                                    <span className="text-sm font-medium">{t.name || t.email}</span>
                                                    <span className="text-[10px] text-gray-500">{t.role || "Teacher"}</span>
                                                </div>
                                            </div>
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                    ) : (
                        <div className="flex items-center justify-between p-4 bg-[#0a0a0a] border border-gray-800 rounded-xl group hover:border-[#D0AD6B]/40 transition-all">
                            <div className="flex items-center gap-4 min-w-0">
                                <div className="w-12 h-12 rounded-lg bg-[#D0AD6B]/10 border border-[#D0AD6B]/30 flex items-center justify-center flex-shrink-0 overflow-hidden">
                                    {teachers.find((t: any) => t.id === selectedTeacherId)?.avatar ? (
                                        <img
                                            src={teachers.find((t: any) => t.id === selectedTeacherId)?.avatar}
                                            alt=""
                                            className="w-full h-full object-cover"
                                        />
                                    ) : (
                                        <span className="text-[#D0AD6B] text-lg font-bold uppercase select-none">
                                            {teachers.find((t: any) => t.id === selectedTeacherId)?.name?.[0] || teachers.find((t: any) => t.id === selectedTeacherId)?.email?.[0] || "T"}
                                        </span>
                                    )}
                                </div>
                                <div className="min-w-0">
                                    <p className="text-sm font-bold text-gray-200">
                                        {teachers.find((t: any) => t.id === selectedTeacherId)?.name || teachers.find((t: any) => t.id === selectedTeacherId)?.email || "Teacher Name"}
                                    </p>
                                    <p className="text-xs text-gray-500">
                                        {teachers.find((t: any) => t.id === selectedTeacherId)?.role || "Subject Specialist"}
                                    </p>
                                </div>
                            </div>
                            <button
                                onClick={handleRemoveTeacher}
                                className="p-2 text-red-500 bg-red-500/10 hover:bg-red-500/20 rounded-lg transition-all flex-shrink-0 ml-2 disabled:opacity-50"
                                disabled={isRemovingTeacher}
                            >
                                {isRemovingTeacher ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4" />}
                            </button>
                        </div>
                    )}
                </div>

                {/* Notification Settings */}
                <div className="bg-[#121212] border border-gray-800 rounded-xl p-6 mb-6 flex items-center justify-between gap-4">
                    <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-2 mb-1">
                            <Bell className="w-4 h-4 text-[#D0AD6B] flex-shrink-0" />
                            <h2 className="text-[#D0AD6B] text-xs font-bold uppercase tracking-wider truncate">NOTIFICATION SETTINGS</h2>
                        </div>
                        <p className="text-gray-500 text-[10px]">Email and in-app notifications enabled for course updates</p>
                    </div>
                    <div className="flex-shrink-0">
                        <CustomSwitch checked={notificationsEnabled} onCheckedChange={() => setNotificationsEnabled(!notificationsEnabled)} />
                    </div>
                </div>

                {/* Publication Summary */}
                <div className="bg-[#0a0a0a] border border-gray-800 rounded-xl p-8 mb-6 hover:border-[#D0AD6B]/20 transition-all">
                    <h2 className="text-[#D0AD6B] text-[10px] font-black uppercase tracking-[0.2em] mb-8">PUBLICATION SUMMARY</h2>
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-y-10 gap-x-8">
                        <div>
                            <p className="text-gray-500 text-[10px] uppercase mb-2 font-black tracking-widest">Course:</p>
                            <p className="text-sm text-gray-200 font-bold">{course.courseName || course.subject}</p>
                        </div>
                        <div>
                            <p className="text-gray-500 text-[10px] uppercase mb-2 font-black tracking-widest">Duration:</p>
                            <p className="text-sm text-gray-200 font-bold">{course.courseLength === "6 Months" ? "Semester" : "Full-Year"}</p>
                        </div>
                        <div>
                            <p className="text-gray-500 text-[10px] uppercase mb-2 font-black tracking-widest">Semester Count:</p>
                            <p className="text-sm text-gray-200 font-bold">{course.semesterCount}</p>
                        </div>
                        <div>
                            <p className="text-gray-500 text-[10px] uppercase mb-2 font-black tracking-widest">Modules:</p>
                            <p className="text-sm font-bold text-[#D0AD6B]">{course.totalModules}</p>
                        </div>
                        <div>
                            <p className="text-gray-500 text-[10px] uppercase mb-2 font-black tracking-widest">Mastery Requirement:</p>
                            <p className="text-sm font-bold text-[#D0AD6B]">{course.masteryRequirement}%</p>
                        </div>
                    </div>
                </div>

                {/* Process done Button */}
                <div className="flex justify-end pb-12 mt-4 border-t border-white/5 pt-8">
                    <button
                        onClick={handlePublishCourse}
                        disabled={isUpdating || isFinalizing}
                        className="bg-[#D4AF37] hover:bg-[#b89a31] text-black font-bold py-4 px-12 rounded-xl flex items-center gap-3 transition-all shadow-xl hover:shadow-[#D4AF37]/20 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed group w-full md:w-auto justify-center"
                    >
                        {isFinalizing || isUpdating ? (
                            <>
                                <span className="text-sm uppercase tracking-widest font-black">Publishing...</span>
                                <Loader2 className="w-5 h-5 animate-spin" />
                            </>
                        ) : (
                            <>
                                <span className="text-sm uppercase tracking-widest font-black text-black">Publish Course</span>
                                <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                            </>
                        )}
                    </button>
                </div>

                {/* Final Generation Overlay */}
                {isFinalizing && (
                    <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
                        <div className="text-center">
                            <Loader2 className="w-12 h-12 text-[#D4AF37] animate-spin mx-auto mb-4" />
                            <h2 className="text-white text-xl font-bold mb-2">PUBLISHING YOUR COURSE</h2>
                            <p className="text-gray-400 text-sm">Saving settings and making course available...</p>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import { Button } from "@/components/ui/button";

import { cn } from "@/utils/utils";
import {
  CheckCircle,
  ChevronLeft,
  ChevronRight,
  FileText,
  HelpCircle,
  MessageSquare,
  Mic,
  Pause,
  Play,
  Volume2,
  X,
} from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { use, useEffect, useRef, useState } from "react";

export default function LessonPage({
  params,
}: {
  params: Promise<{ courseId: string; lessonId: string }>;
}) {
  const router = useRouter();
  const { courseId, lessonId } = use(params);
  const isLoading = false;

  const [isPlaying, setIsPlaying] = useState(true);
  const [currentTime, setCurrentTime] = useState(0);
  const [showBot, setShowBot] = useState(false);
  const [botState, setBotState] = useState<
    "idle" | "listening" | "processing" | "speaking"
  >("idle");
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isVideoReady, setIsVideoReady] = useState(false);
  const [playbackBlocked, setPlaybackBlocked] = useState(false);
  const playAttemptedRef = useRef(false);
  const wasPlayingRef = useRef(false);

  // New state: lesson completed when last transcript segment ends
  const [lessonCompleted, setLessonCompleted] = useState(false);

  // Current lesson selector
  const [currentLesson, setCurrentLesson] = useState<number | null>(1);

  // Mock lesson data with paragraph-style text
  const lessonsData = {
    1: {
      title: "Introduction to Reading Comprehension",
      videoUrl: "/lip_sync.mp4",
      transcript: [
        {
          id: 1,
          text: "Welcome to Lesson 1 on Reading Comprehension. Today, we'll explore the fundamental concepts that make reading an active and engaging process. Reading comprehension is not just about recognizing words on a page; it's about understanding, interpreting, and connecting with the material you're reading. Throughout this lesson, we'll discover how to become more effective readers by developing key strategies and techniques.",
        },
        {
          id: 2,
          text: "Reading comprehension is the ability to process text, understand its meaning, and integrate it with what the reader already knows. It's a complex cognitive process that involves decoding words, understanding their meanings, and making connections between ideas. Good readers actively engage with the text, asking questions, making predictions, and constantly monitoring their understanding as they read.",
        },
        {
          id: 3,
          text: "Effective reading involves multiple levels of understanding. At the most basic level, readers must decode words and understand their literal meanings. Beyond that, readers need to make inferences, identify main ideas and supporting details, and understand the author's purpose and tone. The most skilled readers can also critically evaluate what they read, questioning assumptions and considering alternative perspectives.",
        },
        {
          id: 4,
          text: "Let's explore different reading strategies together that will help you become a more proficient reader. Active reading strategies include previewing the text before reading, asking questions while you read, visualizing the content, making connections to your own experiences, and summarizing key points. By practicing these strategies consistently, you'll find that your comprehension improves significantly, and reading becomes a more enjoyable and rewarding experience.",
        },
      ],
      quiz: [
        {
          question: "What is reading comprehension?",
          options: [
            "Understanding what you read",
            "Reading fast",
            "Memorizing words",
            "Writing essays",
          ],
          correctAnswer: 0,
        },
        {
          question: "Which is a reading strategy?",
          options: [
            "Skipping pages",
            "Active reading",
            "Ignoring context",
            "Reading backwards",
          ],
          correctAnswer: 1,
        },
      ],
    },
    2: {
      title: "Advanced Reading Techniques",
      videoUrl: "/lip_sync.mp4",
      transcript: [
        {
          id: 1,
          text: "Welcome to Lesson 2, where we'll dive into advanced reading techniques that will transform the way you approach texts. As you become a more experienced reader, you'll discover that different reading situations call for different strategies. The techniques we'll explore today will help you read more efficiently while maintaining or even improving your comprehension level.",
        },
        {
          id: 2,
          text: "Skimming and scanning are essential skills for efficient reading that every advanced reader should master. Skimming involves quickly reading through a text to get the general idea or gist, focusing on headings, topic sentences, and key words. Scanning, on the other hand, is used when you're looking for specific information, like a date, name, or fact. Both techniques allow you to process large amounts of text quickly without reading every single word.",
        },
        {
          id: 3,
          text: "Critical reading is a higher-level skill that helps you analyze and evaluate texts more deeply. When you read critically, you're not just accepting what the author says at face value. Instead, you're questioning the author's assumptions, evaluating the strength of their arguments, considering alternative viewpoints, and identifying any biases or logical fallacies. Critical reading is essential for academic success and informed citizenship.",
        },
        {
          id: 4,
          text: "Practice these techniques regularly to become a better reader and develop your own personal reading toolkit. Start by identifying which technique is most appropriate for your reading purpose. If you're researching a topic, you might skim several articles first, then read the most relevant ones more carefully and critically. Remember that becoming an advanced reader is a journey that requires consistent practice and reflection on your reading processes.",
        },
      ],
      quiz: [
        {
          question: "What is skimming?",
          options: [
            "Reading every word",
            "Quickly reading for main ideas",
            "Writing summaries",
            "Memorizing text",
          ],
          correctAnswer: 1,
        },
        {
          question: "What does critical reading involve?",
          options: [
            "Reading slowly",
            "Analyzing and evaluating",
            "Skipping chapters",
            "Reading aloud",
          ],
          correctAnswer: 1,
        },
      ],
    },
    3: {
      title: "Vocabulary Building",
      videoUrl: "/lip_sync.mp4",
      transcript: [
        {
          id: 1,
          text: "Welcome to Lesson 3, where we'll explore the crucial role of vocabulary building in reading comprehension. A strong vocabulary is the foundation of effective reading and communication. The more words you know and understand, the easier it becomes to comprehend complex texts, express yourself clearly, and engage with sophisticated ideas. Today, we'll learn practical strategies for expanding your vocabulary continuously.",
        },
        {
          id: 2,
          text: "Context clues are one of the most powerful tools for understanding unfamiliar words without immediately reaching for a dictionary. When you encounter a new word, look at the surrounding sentences for hints about its meaning. These clues might include definitions, examples, synonyms, antonyms, or general descriptions. Learning to use context clues effectively will make you a more independent and confident reader.",
        },
        {
          id: 3,
          text: "Regular reading is perhaps the single most effective way to naturally expand your vocabulary over time. When you read widely across different genres and subjects, you expose yourself to words in their natural contexts, which helps you understand not just their definitions but also their nuances, connotations, and appropriate usage. Reading diverse materials—from novels to newspapers, from scientific articles to poetry—ensures that you encounter a rich variety of vocabulary.",
        },
        {
          id: 4,
          text: "Keep a vocabulary journal to track new words and reinforce your learning systematically. When you encounter an interesting or unfamiliar word, write it down along with the sentence where you found it, its definition, and perhaps your own example sentence. Review your journal regularly, and try to use your new words in conversation and writing. This active engagement with vocabulary helps transfer words from your passive recognition vocabulary to your active usage vocabulary.",
        },
      ],
      quiz: [
        {
          question: "What are context clues?",
          options: [
            "Dictionary definitions",
            "Hints in surrounding text",
            "Random guesses",
            "Word lists",
          ],
          correctAnswer: 1,
        },
        {
          question: "Best way to build vocabulary?",
          options: [
            "Memorize dictionary",
            "Read regularly",
            "Avoid new words",
            "Use simple words only",
          ],
          correctAnswer: 1,
        },
      ],
    },
    4: {
      title: "Text Analysis & Critical Thinking",
      videoUrl: "/lip_sync.mp4",
      transcript: [
        {
          id: 1,
          text: "Welcome to Lesson 4, where we'll learn to analyze texts critically and think deeply about what we read. Critical thinking in reading goes beyond simple comprehension—it involves actively evaluating the quality, validity, and implications of the information presented. This skill is essential in today's information-rich world, where we're constantly bombarded with messages from various sources, each with their own agendas and perspectives.",
        },
        {
          id: 2,
          text: "Identifying the author's purpose and main argument is the first step in critical text analysis. Ask yourself: Why did the author write this? What are they trying to convince me of? Every piece of writing has a purpose, whether it's to inform, persuade, entertain, or express feelings. Understanding the author's purpose helps you read with appropriate expectations and evaluate whether they've achieved their goal effectively.",
        },
        {
          id: 3,
          text: "Look for supporting evidence and reasoning that the author uses to build their case. Strong arguments are supported by credible evidence such as research findings, expert testimony, statistical data, or logical reasoning. As a critical reader, you should evaluate whether the evidence is relevant, sufficient, and reliable. Are the sources credible? Is the reasoning logical? Are there any gaps in the argument that weaken the author's position?",
        },
        {
          id: 4,
          text: "Question assumptions and evaluate conclusions with a healthy skepticism that leads to deeper understanding. Don't accept everything you read at face value—consider what assumptions the author is making, whether those assumptions are valid, and whether the conclusions logically follow from the evidence presented. Also, think about what perspectives or information might be missing. By developing these critical thinking skills, you'll become not just a better reader, but a more informed and thoughtful person.",
        },
      ],
      quiz: [
        {
          question: "What is critical thinking in reading?",
          options: [
            "Reading fast",
            "Questioning and analyzing",
            "Accepting everything",
            "Skipping details",
          ],
          correctAnswer: 1,
        },
        {
          question: "Why identify author's purpose?",
          options: [
            "To memorize",
            "To understand intent",
            "To copy writing",
            "To find errors",
          ],
          correctAnswer: 1,
        },
      ],
    },
  };

  const getCurrentLessonData = () => {
    if (!currentLesson) return lessonsData[1];
    return lessonsData[currentLesson as keyof typeof lessonsData];
  };

  const handleLessonChange = (lessonNumber: number) => {
    setCurrentLesson(lessonNumber);
    setIsPlaying(true);
    setCurrentTime(0);
    setLessonCompleted(false);
    setViewState("lesson");
    setAnswers({});
    setActiveSegmentId(1);
    setSegmentElapsedTime(0);
    playAttemptedRef.current = false;
    setIsVideoReady(false);
    if (videoRef.current) {
      videoRef.current.pause();
      videoRef.current.src = getCurrentLessonData().videoUrl;
      videoRef.current.load();
      videoRef.current.currentTime = 0;
    }
  };

  // Track which segment is currently active
  const [activeSegmentId, setActiveSegmentId] = useState<number | null>(1);
  // Track elapsed time for current segment
  const [segmentElapsedTime, setSegmentElapsedTime] = useState(0);

  // Calculate duration based on text length (approximately 150 words per minute for reading speed)
  const calculateSegmentDuration = (text: string) => {
    const words = text.split(" ").length;
    const charactersPerSecond = 15; // Average reading speed
    const duration = text.length / charactersPerSecond;
    return Math.max(duration, 3); // Minimum 3 seconds per segment
  };

  // Pre-load video when component mounts
  useEffect(() => {
    const video = videoRef.current;
    if (video) {
      video.load();
      video.preload = "auto";
    }
  }, []);

  // Reset on page reload/revisit and AUTO START
  useEffect(() => {
    // Reset everything when component mounts (new visit)
    setActiveSegmentId(1);
    setSegmentElapsedTime(0);
    setLessonCompleted(false);
    setIsPlaying(false);
    playAttemptedRef.current = false;
    setIsVideoReady(false);

    if (videoRef.current) {
      videoRef.current.currentTime = 0;
    }
  }, [lessonId]); // Trigger when lessonId changes (new visit)

  // Video progress + segment control logic - based on text length
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    // Force source refresh for HTTP VPS
    video.src = getCurrentLessonData().videoUrl;
    video.load();

    const handleTimeUpdate = () => {
      const time = video.currentTime;
      setCurrentTime(time);

      if (!isPlaying) return;

      const data = getCurrentLessonData();
      if (!data?.transcript?.length || activeSegmentId === null) return;

      const currentSegment = data.transcript.find(
        (seg) => seg.id === activeSegmentId,
      );
      if (!currentSegment) return;
    };

    const handlePlay = () => {
      console.log("Video playing event");
      setIsPlaying(true);
    };

    const handlePause = () => {
      console.log("Video pause event");
      if (document.visibilityState === "visible") {
        setIsPlaying(false);
      }
    };

    const handleLoadedMetadata = () => {
      setIsVideoReady(true);
    };

    const handleCanPlay = () => {
      setIsVideoReady(true);
    };

    video.addEventListener("timeupdate", handleTimeUpdate);
    video.addEventListener("play", handlePlay);
    video.addEventListener("pause", handlePause);
    video.addEventListener("loadedmetadata", handleLoadedMetadata);
    video.addEventListener("canplay", handleCanPlay);

    return () => {
      video.removeEventListener("timeupdate", handleTimeUpdate);
      video.removeEventListener("play", handlePlay);
      video.removeEventListener("pause", handlePause);
      video.removeEventListener("loadedmetadata", handleLoadedMetadata);
      video.removeEventListener("canplay", handleCanPlay);
    };
  }, [currentLesson, lessonId]); // Re-attach when element remounts

  // Handle visibility change separately
  useEffect(() => {
    const handleVisibilityChange = () => {
      const video = videoRef.current;
      if (!video) return;

      if (document.visibilityState === "hidden") {
        wasPlayingRef.current = isPlaying;
      } else if (
        document.visibilityState === "visible" &&
        wasPlayingRef.current
      ) {
        video.play().catch((e) => console.log("Auto-resume failed:", e));
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () =>
      document.removeEventListener("visibilitychange", handleVisibilityChange);
  }, [isPlaying]);

  // Separate timer for segment duration based on text length
  useEffect(() => {
    console.log(
      "Segment timer check - isPlaying:",
      isPlaying,
      "activeSegmentId:",
      activeSegmentId,
      "isVideoReady:",
      isVideoReady,
    );

    // Don't start timer until video is actually playing
    if (!isPlaying || activeSegmentId === null || !isVideoReady) {
      console.log("Segment timer NOT starting");
      return;
    }

    console.log("Segment timer STARTING for segment", activeSegmentId);

    const data = getCurrentLessonData();
    if (!data?.transcript?.length) return;

    const currentSegment = data.transcript.find(
      (seg) => seg.id === activeSegmentId,
    );
    if (!currentSegment) return;

    const segmentDuration = calculateSegmentDuration(currentSegment.text);
    console.log(
      `Segment ${activeSegmentId} duration: ${segmentDuration.toFixed(1)}s`,
    );

    const interval = setInterval(() => {
      setSegmentElapsedTime((prev) => {
        const newTime = prev + 0.1;

        // Check if segment duration is complete
        if (newTime >= segmentDuration) {
          const currentIndex = data.transcript.findIndex(
            (seg) => seg.id === activeSegmentId,
          );

          // Check if this is the last segment
          if (currentIndex === data.transcript.length - 1) {
            // Last segment - pause video and mark lesson as completed
            if (videoRef.current) {
              videoRef.current.pause();
            }
            setIsPlaying(false);
            setLessonCompleted(true);
            console.log("All segments completed!");
            clearInterval(interval);
          } else {
            // Move to next segment automatically
            const nextSegment = data.transcript[currentIndex + 1];
            setActiveSegmentId(nextSegment.id);
            setSegmentElapsedTime(0);
            if (videoRef.current) {
              videoRef.current.currentTime = 0;
            }
            console.log(
              `Auto-progressing to segment ${nextSegment.id} after ${segmentDuration.toFixed(1)}s`,
            );
          }
          return 0;
        }

        return newTime;
      });
    }, 100);

    return () => {
      console.log("Segment timer STOPPED for segment", activeSegmentId);
      clearInterval(interval);
    };
  }, [isPlaying, activeSegmentId, currentLesson]);

  // Simplified control playback + HTTP/VPS optimization
  useEffect(() => {
    const video = videoRef.current;
    if (!video || !isVideoReady) return;

    const syncPlayback = async () => {
      try {
        if (isPlaying && !showBot && !lessonCompleted) {
          if (video.paused) {
            try {
              await video.play();
              setPlaybackBlocked(false);
            } catch (e) {
              console.log("HTTP/VPS Blocked autoplay:", e);
              setPlaybackBlocked(true);
              setIsPlaying(false);
            }
          }
        } else {
          if (!video.paused) video.pause();
        }
      } catch (err) {
        console.log("Sync playback error:", err);
      }
    };

    syncPlayback();
  }, [isPlaying, showBot, lessonCompleted, isVideoReady]);

  // Handle initial user interaction to wake up audio/video (Crucial for HTTP VPS)
  useEffect(() => {
    const handleWakeUp = () => {
      if (playbackBlocked && !isPlaying && videoRef.current) {
        videoRef.current
          .play()
          .then(() => {
            setPlaybackBlocked(false);
            setIsPlaying(true);
          })
          .catch(() => {});
      }
    };

    window.addEventListener("click", handleWakeUp);
    window.addEventListener("touchstart", handleWakeUp);
    return () => {
      window.removeEventListener("click", handleWakeUp);
      window.removeEventListener("touchstart", handleWakeUp);
    };
  }, [playbackBlocked, isPlaying]);

  // Auto-scroll transcript based on active segment
  useEffect(() => {
    const data = getCurrentLessonData();
    if (!data?.transcript || activeSegmentId === null) return;

    const activeIndex = data.transcript.findIndex(
      (seg) => seg.id === activeSegmentId,
    );

    if (activeIndex !== -1 && scrollContainerRef.current) {
      const el = scrollContainerRef.current.children[
        activeIndex
      ] as HTMLElement;
      if (el) el.scrollIntoView({ behavior: "smooth", block: "center" });
    }
  }, [activeSegmentId, currentLesson]);

  const handleBotClick = () => {
    setIsPlaying(false);
    setShowBot(true);
    setBotState("listening");
    setTimeout(() => setBotState("processing"), 2000);
    setTimeout(() => setBotState("speaking"), 4000);
  };

  const handleTranscriptClick = (segmentId: number) => {
    const video = videoRef.current;
    if (video) {
      video.currentTime = 0;
      setCurrentTime(0);
      setActiveSegmentId(segmentId);
      setSegmentElapsedTime(0);
      setIsPlaying(true);
      setLessonCompleted(false);
      console.log(`Jumped to segment ${segmentId}`);
    }
  };

  // Quiz logic
  const [viewState, setViewState] = useState<"lesson" | "quiz" | "result">(
    "lesson",
  );
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [score, setScore] = useState(0);

  const handleQuizClick = () => {
    setCurrentLesson(null);
    setViewState("quiz");
    setIsPlaying(false);
    setLessonCompleted(false);
  };

  const handleStartQuiz = () => {
    setCurrentLesson(null);
    setViewState("quiz");
    setIsPlaying(false);
    setLessonCompleted(false);
  };

  const handleOptionSelect = (qIndex: number, oIndex: number) => {
    setAnswers((prev) => ({ ...prev, [qIndex]: oIndex }));
  };

  const handleSubmitQuiz = () => {
    const data = getCurrentLessonData();
    if (!data?.quiz) return;

    let correct = 0;
    data.quiz.forEach((q, i) => {
      if (answers[i] === q.correctAnswer) correct++;
    });
    setScore(correct);
    setViewState("result");
  };

  const handleBackToLesson = () => {
    setViewState("lesson");
    setCurrentLesson(1);
    setLessonCompleted(false);
    setActiveSegmentId(1);
    setSegmentElapsedTime(0);
  };

  if (isLoading) return <div className="p-8 text-white">Loading lesson...</div>;

  const currentLessonData = getCurrentLessonData();

  return (
    <div className="flex h-screen text-foreground overflow-hidden relative rounded-2xl">
      {/* Sidebar */}
      <div className="bg-[#1C1C1C] border-r border-[#333] flex flex-col hidden lg:flex">
        <div className="p-6 border-b border-[#333]">
          <Link
            href={`/student/courses/${courseId}`}
            className="text-sm text-gray-400 hover:text-[#D4AF37] flex items-center gap-2 mb-4"
          >
            <ChevronLeft className="w-4 h-4" /> Back to Course
          </Link>
          <h2 className="text-[#D4AF37] font-semibold text-lg">
            {currentLesson ? currentLessonData.title : "Lesson Quiz"}
          </h2>
          <p className="text-xs text-gray-500 mt-1">
            Module 1: Reading & Comprehension
          </p>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-2">
          {[1, 2, 3, 4].map((i) => (
            <div
              key={i}
              onClick={() => handleLessonChange(i)}
              className={cn(
                "p-3 rounded-lg flex items-center gap-3 cursor-pointer transition-all",
                i === currentLesson && viewState === "lesson"
                  ? "bg-[#D4AF37]/10 border border-[#D4AF37]/30"
                  : "hover:bg-[#252525]",
              )}
            >
              <div
                className={cn(
                  "w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold",
                  i === currentLesson && viewState === "lesson"
                    ? "bg-[#D4AF37] text-black"
                    : "bg-[#333] text-gray-400",
                )}
              >
                {i === currentLesson && viewState === "lesson" ? (
                  <Play className="w-3 h-3 fill-current" />
                ) : (
                  i
                )}
              </div>
              <div>
                <p
                  className={cn(
                    "text-sm font-medium",
                    i === currentLesson && viewState === "lesson"
                      ? "text-[#D4AF37]"
                      : "text-gray-300",
                  )}
                >
                  Lesson {i}
                </p>
                <p className="text-[10px] text-gray-500">10 mins</p>
              </div>
            </div>
          ))}
          <div
            onClick={handleQuizClick}
            className={cn(
              "p-3 rounded-lg flex items-center gap-3 cursor-pointer mt-4 transition-all",
              viewState === "quiz" || viewState === "result"
                ? "bg-[#D4AF37]/10 border border-[#D4AF37]/30"
                : "hover:bg-[#252525]",
            )}
          >
            <div
              className={cn(
                "w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold",
                viewState === "quiz" || viewState === "result"
                  ? "bg-[#D4AF37] text-black"
                  : "bg-[#333] text-gray-400",
              )}
            >
              <HelpCircle className="w-3 h-3" />
            </div>
            <div>
              <p
                className={cn(
                  "text-sm font-medium",
                  viewState === "quiz" || viewState === "result"
                    ? "text-[#D4AF37]"
                    : "text-gray-300",
                )}
              >
                Lesson Quiz
              </p>
              <p className="text-[10px] text-gray-500">
                {currentLessonData.quiz?.length || 0} Questions
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col relative bg-[#111]">
        {/* Header */}
        <div className="h-16 border-b border-[#333] flex items-center justify-between px-6 bg-[#161616]">
          <h1 className="text-lg font-medium text-white">
            {currentLesson ? currentLessonData.title : "Lesson Quiz"}
          </h1>
          <div className="flex items-center gap-4">
            {viewState === "lesson" && (
              <Button
                size="sm"
                onClick={handleStartQuiz}
                className="bg-[#D4AF37] hover:bg-[#c4a02f] text-black font-bold"
              >
                Take Quiz <ChevronRight className="w-4 h-4 ml-1" />
              </Button>
            )}
            {viewState !== "lesson" && (
              <Button
                onClick={handleBackToLesson}
                variant="outline"
                className="border-[#333] bg-[#222] text-gray-300 hover:text-white"
              >
                Back to Lesson
              </Button>
            )}
          </div>
        </div>

        {/* Lesson View */}
        {viewState === "lesson" && (
          <div className="flex-1 overflow-hidden flex flex-col lg:flex-row relative">
            {/* Transcript */}
            <div
              className="flex-1 p-8 overflow-y-auto border-r border-[#333] bg-[#111]"
              ref={scrollContainerRef}
            >
              <h3 className="text-[#D4AF37] font-semibold mb-6 flex items-center gap-2">
                <FileText className="w-4 h-4" /> Transcript
              </h3>
              <div className="space-y-6 max-w-2xl mx-auto">
                {currentLessonData.transcript.map((segment) => {
                  const isActive = activeSegmentId === segment.id; // Keep focused even if temporarily paused
                  const isCurrentlyPlaying = isActive && isPlaying;
                  return (
                    <div
                      key={segment.id}
                      className={cn(
                        "transition-all duration-300 p-4 rounded-xl cursor-pointer hover:bg-[#1f1f1f]",
                        isActive
                          ? "bg-[#252525] border-l-4 border-[#D4AF37] opacity-100 scale-105 shadow-md"
                          : "opacity-50 text-gray-500 border-l-4 border-transparent",
                      )}
                      onClick={() => handleTranscriptClick(segment.id)}
                    >
                      <p
                        className={cn(
                          "leading-relaxed",
                          isActive
                            ? "text-white font-medium text-sm"
                            : "text-gray-500 text-base",
                          !isCurrentlyPlaying && isActive && "text-white/70",
                        )}
                      >
                        {segment.text}
                      </p>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Video + Bot Area */}
            <div className="w-full lg:w-112.5 bg-black p-6 flex flex-col border-l border-[#333] relative">
              <div className="relative aspect-4/3 bg-[#1a1a1a] rounded-2xl overflow-hidden shadow-2xl border border-[#333] mb-6">
                <video
                  ref={videoRef}
                  muted
                  autoPlay
                  loop
                  className="absolute inset-0 w-full h-full object-cover"
                  src={currentLessonData.videoUrl}
                  playsInline
                  webkit-playsinline="true"
                  preload="auto"
                  onLoadedData={() => setIsVideoReady(true)}
                  onCanPlay={() => setIsVideoReady(true)}
                  onError={() => {
                    console.log("Video loading error - likely HTTP/CORS issue");
                    setPlaybackBlocked(true);
                  }}
                />

                {/* Playback Blocked Overlay (HTTP Fallback) */}
                {playbackBlocked && (
                  <div
                    className="absolute inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center p-6 text-center cursor-pointer z-10"
                    onClick={() => {
                      if (videoRef.current) {
                        videoRef.current.play();
                        setPlaybackBlocked(false);
                        setIsPlaying(true);
                      }
                    }}
                  >
                    <div className="w-16 h-16 rounded-full bg-[#D4AF37] flex items-center justify-center mb-4 animate-bounce shadow-xl">
                      <Play className="w-8 h-8 text-black fill-current ml-1" />
                    </div>
                    <p className="text-white font-bold text-lg mb-1">
                      Click to Start Lesson
                    </p>
                    <p className="text-gray-300 text-xs">
                      Your browser blocked the automatic video start
                    </p>
                  </div>
                )}

                {/* Play/Pause */}
                <div className="absolute bottom-6 left-0 right-0 flex justify-center gap-6">
                  <Button
                    size="icon"
                    className="rounded-full w-12 h-12 bg-[#D4AF37] hover:bg-[#c4a02f] text-black shadow-lg"
                    onClick={() => setIsPlaying(!isPlaying)}
                    disabled={lessonCompleted}
                  >
                    {isPlaying ? (
                      <Pause className="fill-current" />
                    ) : (
                      <Play className="fill-current ml-1" />
                    )}
                  </Button>
                </div>

                {/* Lesson Completed Overlay */}
                {lessonCompleted && (
                  <div className="absolute inset-0 bg-black/80 flex items-center justify-center z-20">
                    <div className="text-center p-8 bg-[#1C1C1C] rounded-2xl border border-[#D4AF37]/40 max-w-sm mx-4">
                      <CheckCircle className="w-16 h-16 text-[#D4AF37] mx-auto mb-4" />
                      <h3 className="text-2xl font-bold text-white mb-3">
                        Lesson Completed!
                      </h3>
                      <p className="text-gray-400 mb-6">
                        You&#39;ve watched all the explained sections.
                      </p>
                      <div className="flex gap-4 justify-center">
                        <Button
                          variant="outline"
                          className="border-[#D4AF37]/50 text-[#D4AF37] hover:bg-[#D4AF37]/10"
                          onClick={() => {
                            if (videoRef.current) {
                              videoRef.current.currentTime = 0;
                              setCurrentTime(0);
                              setLessonCompleted(false);
                              setActiveSegmentId(1);
                              setSegmentElapsedTime(0);
                              setIsPlaying(true);
                            }
                          }}
                        >
                          Replay Lesson
                        </Button>
                        <Button
                          className="bg-[#D4AF37] hover:bg-[#c4a02f] text-black"
                          onClick={handleStartQuiz}
                        >
                          Take Quiz
                        </Button>
                      </div>
                    </div>
                  </div>
                )}
              </div>

              {/* AI Tutor / Bot Section */}
              <div className="bg-[#1C1C1C] rounded-xl p-4 border border-[#333] flex-1 flex flex-col">
                {!showBot ? (
                  <div className="flex-1 flex flex-col items-center justify-center text-center p-6">
                    <div className="w-20 h-20 bg-[#252525] rounded-full overflow-hidden border-2 border-[#D4AF37]/30 mb-4 shadow-xl">
                      <Image
                        width={100}
                        height={100}
                        src="/assets/avatar-2.jpg"
                        className="w-full h-full object-cover"
                        alt="AI Tutor"
                      />
                    </div>
                    <h3 className="text-white font-semibold mb-2">
                      Need help?
                    </h3>
                    <p className="text-gray-400 text-sm mb-6">
                      Ask the AI tutor about any confusing topics
                    </p>
                    <Button
                      onClick={handleBotClick}
                      className="bg-[#D4AF37] hover:bg-[#c4a02f] text-black font-bold h-10 px-6 rounded-full"
                    >
                      Ask AI Assistant
                    </Button>
                  </div>
                ) : (
                  <div className="flex-1 flex flex-col">
                    <div className="flex justify-between items-center mb-4 border-b border-[#333] pb-2">
                      <div className="flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-[#D4AF37] animate-pulse" />
                        <span className="text-[#D4AF37] font-medium">
                          AI Tutor Active
                        </span>
                      </div>
                      <button
                        onClick={() => setShowBot(false)}
                        className="text-gray-500 hover:text-white"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    </div>

                    <div className="flex-1 flex flex-col items-center justify-center gap-4">
                      {botState === "listening" && (
                        <>
                          <div className="w-24 h-24 rounded-full border-2 border-[#D4AF37] p-1 animate-pulse">
                            <div className="w-full h-full rounded-full overflow-hidden">
                              <Image
                                width={100}
                                height={100}
                                src="/assets/avatar-2.jpg"
                                className="w-full h-full object-cover"
                                alt="AI Tutor"
                              />
                            </div>
                          </div>
                          <div className="flex items-center gap-2">
                            <Mic className="w-4 h-4 text-[#D4AF37] animate-bounce" />
                            <p className="text-[#D4AF37] font-medium">
                              I&#39;m listening...
                            </p>
                          </div>
                        </>
                      )}
                      {botState === "processing" && (
                        <>
                          <div className="flex gap-1">
                            <div className="w-3 h-3 bg-[#D4AF37] rounded-full animate-bounce delay-0" />
                            <div className="w-3 h-3 bg-[#D4AF37] rounded-full animate-bounce delay-100" />
                            <div className="w-3 h-3 bg-[#D4AF37] rounded-full animate-bounce delay-200" />
                          </div>
                          <p className="text-gray-400">Thinking...</p>
                        </>
                      )}
                      {botState === "speaking" && (
                        <>
                          <div className="w-24 h-24 rounded-full border-2 border-[#22C55E] p-1">
                            <div className="w-full h-full rounded-full overflow-hidden">
                              <Image
                                width={100}
                                height={100}
                                src="/assets/avatar-2.jpg"
                                className="w-full h-full object-cover"
                                alt="AI Tutor"
                              />
                            </div>
                          </div>
                          <div className="bg-[#252525] p-4 rounded-xl border border-[#333] max-w-xs text-sm text-gray-200 shadow-lg">
                            &#39;Inferential reading is essentially reading
                            between the lines. It&#39;s using clues to
                            understand what isn&#39;t explicitly stated.&#39;
                          </div>
                          <div className="flex items-center gap-2 text-[#22C55E]">
                            <Volume2 className="w-4 h-4 animate-pulse" />
                            <p className="text-xs font-medium">
                              AI is replying...
                            </p>
                          </div>
                        </>
                      )}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {/* Quiz View - keeping same as before */}
        {viewState === "quiz" && (
          <div className="flex-1 overflow-y-auto p-8 bg-[#111]">
            <div className="max-w-3xl mx-auto">
              <h2 className="text-2xl font-bold text-[#D4AF37] mb-6">
                Lesson Quiz
              </h2>
              <div className="space-y-8">
                {currentLessonData.quiz?.map((q, qIdx) => (
                  <div
                    key={qIdx}
                    className="bg-[#1C1C1C] border border-[#333] rounded-xl p-6"
                  >
                    <h3 className="text-lg font-medium text-white mb-4">
                      Question {qIdx + 1}: {q.question}
                    </h3>
                    <div className="space-y-3">
                      {q.options.map((option, oIdx) => (
                        <div
                          key={oIdx}
                          onClick={() => handleOptionSelect(qIdx, oIdx)}
                          className={cn(
                            "p-4 rounded-lg border cursor-pointer flex items-center gap-3 transition-all",
                            answers[qIdx] === oIdx
                              ? "bg-[#D4AF37]/10 border-[#D4AF37] text-[#D4AF37]"
                              : "bg-transparent border-[#333] text-gray-300 hover:bg-[#252525]",
                          )}
                        >
                          <div
                            className={cn(
                              "w-5 h-5 rounded-full border flex items-center justify-center",
                              answers[qIdx] === oIdx
                                ? "border-[#D4AF37]"
                                : "border-gray-500",
                            )}
                          >
                            {answers[qIdx] === oIdx && (
                              <div className="w-3 h-3 rounded-full bg-[#D4AF37]" />
                            )}
                          </div>
                          {option}
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
              <div className="flex justify-end mt-8 pb-12">
                <Button
                  onClick={handleSubmitQuiz}
                  className="bg-[#D4AF37] hover:bg-[#c4a02f] text-black font-bold h-12 px-8 rounded-full text-lg"
                >
                  Submit Quiz
                </Button>
              </div>
            </div>
          </div>
        )}

        {/* Result View - keeping same as before */}
        {viewState === "result" && (
          <div className="flex-1 overflow-y-auto p-8 bg-[#111] flex items-center justify-center">
            <div className="max-w-3xl w-full">
              <div className="text-center mb-12">
                <div className="w-20 h-20 bg-[#D4AF37]/20 rounded-full flex items-center justify-center mx-auto mb-6">
                  <CheckCircle className="w-10 h-10 text-[#D4AF37]" />
                </div>
                <h2 className="text-4xl font-bold text-white mb-2">
                  Quiz Complete!
                </h2>
                <p className="text-gray-400">
                  Great job! Here&#39;s how you did:
                </p>

                <div className="flex justify-center gap-12 mt-8">
                  <div className="text-center">
                    <div className="text-3xl font-bold text-[#D4AF37]">
                      {score * 10}
                    </div>
                    <div className="text-xs uppercase text-gray-500 tracking-wider">
                      Points Earned
                    </div>
                  </div>
                  <div className="text-center">
                    <div className="text-3xl font-bold text-[#D4AF37]">
                      {score}/{currentLessonData.quiz?.length}
                    </div>
                    <div className="text-xs uppercase text-gray-500 tracking-wider">
                      Correct Answers
                    </div>
                  </div>
                  <div className="text-center">
                    <div className="text-3xl font-bold text-[#D4AF37]">
                      {Math.round(
                        (score / (currentLessonData.quiz?.length || 1)) * 100,
                      )}
                      %
                    </div>
                    <div className="text-xs uppercase text-gray-500 tracking-wider">
                      Accuracy
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-6">
                {currentLessonData.quiz?.map((q, qIdx) => {
                  const isCorrect = answers[qIdx] === q.correctAnswer;
                  return (
                    <div
                      key={qIdx}
                      className="bg-[#1C1C1C] border border-[#333] rounded-xl p-6"
                    >
                      <div className="flex justify-between mb-4">
                        <h3 className="text-lg font-medium text-white">
                          Question {qIdx + 1}
                        </h3>
                      </div>
                      <p className="text-gray-300 mb-4">{q.question}</p>

                      <div className="space-y-2">
                        <div
                          className={cn(
                            "p-4 rounded-lg border flex justify-between items-center",
                            isCorrect
                              ? "bg-[#22C55E]/10 border-[#22C55E] text-[#22C55E]"
                              : "bg-[#EF4444]/10 border-[#EF4444] text-[#EF4444]",
                          )}
                        >
                          <span>
                            Your Answer: {q.options[answers[qIdx]] || "Skipped"}
                          </span>
                          {isCorrect ? (
                            <CheckCircle className="w-5 h-5" />
                          ) : (
                            <X className="w-5 h-5" />
                          )}
                        </div>
                        {!isCorrect && (
                          <div className="p-4 rounded-lg border border-[#22C55E] bg-[#22C55E]/5 text-[#22C55E] flex justify-between items-center">
                            <span>
                              Correct Answer: {q.options[q.correctAnswer]}
                            </span>
                            <CheckCircle className="w-5 h-5" />
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>

              <div className="flex justify-center gap-4 mt-12 pb-12">
                <Button
                  onClick={() => setViewState("quiz")}
                  variant="outline"
                  className="border-[#333] bg-transparent text-[#D4AF37] hover:bg-[#D4AF37]/10 h-12 px-8"
                >
                  Try Again
                </Button>
                <Button
                  onClick={() => router.push(`/student/courses/${courseId}`)}
                  className="bg-[#D4AF37] hover:bg-[#c4a02f] text-black font-bold h-12 px-8"
                >
                  Go Back Home
                </Button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Floating Bot Button */}
      {!showBot && viewState === "lesson" && (
        <button
          onClick={handleBotClick}
          className="absolute bottom-8 right-8 w-14 h-14 bg-[#D4AF37] rounded-full shadow-xl flex items-center justify-center hover:bg-[#c4a02f] transition-transform hover:scale-110 z-50 border-4 border-[#111]"
          title="Ask AI Assistant"
        >
          <MessageSquare className="w-6 h-6 text-black fill-current" />
        </button>
      )}
    </div>
  );
}

"use client";

import React from "react";
import { BookOpen, TrendingUp, ChevronRight } from "lucide-react";
import Link from "next/link";
import { useGetAllCoursesQuery } from "@/lib/feature/courses/coursesApi";

export default function MyCoursesPage() {
  const { data: response, isLoading } = useGetAllCoursesQuery();
  const courses = response?.data || [];

  if (isLoading) return <div className="p-6 text-white">Loading courses...</div>;

  return (
    <div className="min-h-screen bg-[#111] text-foreground">
      <div className="mb-8 p-6 bg-[#1C1C1C] border border-[#333] rounded-xl">
        <h1 className="text-xl font-bold text-[#D4AF37] mb-1">My Courses</h1>
        <p className="text-gray-400 text-sm">Track your progress across all subjects</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {courses?.map((course: any) => {
          const progress = course.progress || 0;
          const mastery = course.mastery || 0;
          const title = course.courseName || course.title || "Untitled Course";

          return (
            <Link href={`/student/courses/${course.id}`} key={course.id} className="block group">
              <div className="bg-[#1C1C1C] border border-[#333] rounded-xl p-6 transition-all hover:border-[#D4AF37]/50 hover:bg-[#252525]">
                <div className="flex justify-between items-start mb-6">
                  <div className="w-10 h-10 bg-[#2A2A2A] rounded-lg flex items-center justify-center text-gray-300">
                    <BookOpen className="w-5 h-5" />
                  </div>
                  <ChevronRight className="w-5 h-5 text-gray-600 group-hover:text-[#D4AF37] transition-colors" />
                </div>

                <h2 className="text-lg font-semibold text-[#D4AF37] mb-6">{title}</h2>

                <div className="space-y-4">
                  {/* Progress */}
                  <div>
                    <div className="flex justify-between text-xs text-gray-400 mb-2">
                      <div className="flex items-center gap-1.5">
                        <BookOpen className="w-3.5 h-3.5" />
                        <span>Progress</span>
                      </div>
                      <span className="text-white font-medium">{progress}%</span>
                    </div>
                    <div className="h-1.5 bg-[#333] rounded-full overflow-hidden">
                      <div className="h-full bg-[#22C55E]" style={{ width: `${progress}%` }} />
                    </div>
                  </div>

                  {/* Mastery */}
                  <div>
                    <div className="flex justify-between text-xs text-gray-400 mb-2">
                      <div className="flex items-center gap-1.5">
                        <TrendingUp className="w-3.5 h-3.5" />
                        <span>Mastery</span>
                      </div>
                      <span className="text-[#D4AF37] font-medium">{mastery}%</span>
                    </div>
                    <div className="h-1.5 bg-[#333] rounded-full overflow-hidden">
                      <div className="h-full bg-white" style={{ width: `${mastery}%` }} />
                      {/* Note: Design shows white mastery bar? or light gray. Using white for now based on image 1 description request (looks white in small thumbnail) or maybe sticking to gold if consistent. Image 1 shows Mastery as White bar? Let's check image 1 again. 
                       Actually looking at the small thumbnail, mastery bar seems white. I will stick to white. */}
                    </div>
                  </div>
                </div>
              </div>
            </Link>
          );
        })}
      </div>
    </div>
  );
}

"use client";
import { useState } from 'react';
import { ChevronLeft, ChevronDown, ChevronRight, CheckCircle2, Loader, AlertCircle } from 'lucide-react';
import { useParams, useRouter } from 'next/navigation';
import { useGetTeacherCourseDetailsQuery } from '@/lib/feature/courses/coursesApi';

// --- Sub-components ---

const LessonItem = ({ title, type, duration, isCompleted = true }: { title: string; type: string; duration?: string; isCompleted?: boolean }) => (
  <div className="flex items-center justify-between  p-4 bg-[#1A1A1A]/40 border-l-2 border-[#C08F42] hover:bg-[#1A1A1A] transition-colors mb-1">
    <div className="flex items-center gap-4">
      <CheckCircle2 size={18} className={isCompleted ? "text-[#C08F42]" : "text-zinc-600"} />
      <div>
        <h4 className="text-zinc-200 text-sm font-medium">{title}</h4>
        <p className="text-zinc-500 text-xs mt-0.5">{type}</p>
      </div>
    </div>
    <span className="text-zinc-500 text-xs">{duration}</span>
  </div>
);

const ModuleAccordion = ({ title, progress, duration, isOpen, onClick, children }: { title: string; progress: string; duration: string; isOpen: boolean; onClick: () => void; children?: React.ReactNode }) => (
  <div className="border border-white/10 rounded-lg overflow-hidden mb-3">
    <button 
      onClick={onClick}
      className="w-full flex items-center justify-between p-5 bg-[#121212] hover:bg-[#181818] transition-colors"
    >
      <div className="flex items-center gap-4">
        {isOpen ? <ChevronDown size={20} className="text-[#C08F42]" /> : <ChevronRight size={20} className="text-zinc-400" />}
        <div className="text-left">
          <h3 className="text-zinc-100 font-semibold text-[15px]">{title}</h3>
          <p className="text-zinc-500 text-xs mt-1">{progress}</p>
        </div>
      </div>
      <span className="text-zinc-500 text-xs font-light">{duration}</span>
    </button>
    {isOpen && (
      <div className="bg-[#0F0F0F] p-4 border-t border-white/5">
        {children}
      </div>
    )}
  </div>
);

// --- Main Page Component ---

export default function CourseSyllabus() {
  const router = useRouter();
  const params = useParams();
  const courseId = params.courseDetails as string;
  
  const [openModuleIndex, setOpenModuleIndex] = useState<number | null>(0);

  const { data, isLoading, error } = useGetTeacherCourseDetailsQuery(courseId);

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#0A0A0A] flex flex-col items-center justify-center gap-4">
        <Loader className="w-12 h-12 text-[#C08F42] animate-spin" />
        <p className="text-zinc-400 animate-pulse">Fetching syllabus details...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-[#0A0A0A] flex flex-col items-center justify-center p-6 text-center">
        <AlertCircle className="w-16 h-16 text-red-500 mb-4" />
        <h2 className="text-2xl font-bold text-zinc-100 mb-2">Error Loading Syllabus</h2>
        <p className="text-zinc-400 max-w-md">
          {(error as any)?.data?.message || "We couldn't retrieve the course details. Please try again later."}
        </p>
        <button 
          onClick={() => router.back()}
          className="mt-8 px-6 py-2 bg-[#C08F42]/10 border border-[#C08F42]/20 text-[#C08F42] rounded-lg hover:bg-[#C08F42]/20 transition-all font-medium"
        >
          Go Back
        </button>
      </div>
    );
  }

  const course = data?.data;
  if (!course) return null;

  const stats = [
    { label: "MASTERY REQUIREMENT", value: `${course.stats?.masteryRequirement || 0}%` },
    { label: "MODULES/COMPLETED", value: `${course.stats?.modulesTotal || 0}` },
    { label: "LESSONS/COMPLETED", value: `${course.stats?.lessonsTotal || 0}` },
    { label: "ASSESSMENTS/COMPLETED", value: `${course.stats?.assessmentsTotal || 0}` },
    { label: "COURSE LENGTH", value: course.stats?.courseLength || course.courseLength, primary: true },
  ];

  return (
    <div className=" bg-[#0A0A0A] text-zinc-300 p-6 md:p-12">
      <div className="max-w-6xl mx-auto">
        
        {/* Header Section */}
        <header className="mb-10 p-8 bg-[#121212] border border-white/10 rounded-xl relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-10">
             <div className="text-8xl font-black text-[#C08F42] select-none uppercase tracking-tighter font-sans">
                {course.subject}
             </div>
          </div>
          
          <button 
            onClick={() => router.back()}
            className="flex items-center gap-2 text-[#C08F42] text-sm font-medium mb-6 hover:opacity-80 transition-opacity"
          >
            <ChevronLeft size={18} /> Back
          </button>
          
          <h1 className="text-4xl font-bold text-[#C08F42] mb-3">{course.courseName}</h1>
          <p className="text-zinc-400 max-w-3xl leading-relaxed">
            {course.description || course.generatedCourseName}
          </p>
          
          <div className="mt-6 flex gap-4 text-xs font-medium uppercase tracking-widest text-zinc-500">
             <span className="flex items-center gap-1.5"><div className="w-1.5 h-1.5 rounded-full bg-[#C08F42]" /> {course.targetGradeLevel}</span>
             <span className="flex items-center gap-1.5"><div className="w-1.5 h-1.5 rounded-full bg-[#C08F42]" /> {course.courseLength}</span>
             <span className="flex items-center gap-1.5"><div className="w-1.5 h-1.5 rounded-full bg-[#C08F42]" /> {course.semesterCount} Semesters</span>
          </div>
        </header>

        {/* Syllabus Container */}
        <section className="bg-[#121212] border border-white/10 rounded-xl p-8">
          <div className="mb-8">
            <h2 className="text-[#C08F42] font-bold tracking-widest text-2xl mb-1 uppercase">COURSE SYLLABUS</h2>
            <p className="text-zinc-500 text-sm uppercase tracking-tight">Modules, lessons, and assessments</p>
            <hr className="mt-6 border-white/5" />
          </div>

          {/* Modules */}
          {course.modules?.map((module, mIdx) => (
            <ModuleAccordion 
              key={module.id}
              title={`Module ${module.moduleNumber}: ${module.moduleTitle}`} 
              progress={`${module.studyTopics?.length || 0} Topics`} 
              duration={module.voiceData?.duration_seconds ? `${Math.ceil(module.voiceData.duration_seconds / 60)} min audio` : ""}
              isOpen={openModuleIndex === mIdx}
              onClick={() => setOpenModuleIndex(openModuleIndex === mIdx ? null : mIdx)}
            >
              {module.introduction && (
                <p className="text-zinc-400 text-sm italic mb-6 leading-relaxed border-l-2 border-white/5 pl-4 py-1">
                  &quot;{module.introduction}&quot;
                </p>
              )}

              {module.studyTopics && module.studyTopics.length > 0 && (
                <div className="mb-6">
                  <h5 className="text-[#C08F42] text-[10px] font-bold tracking-[0.2em] mb-4">LESSONS / TOPICS</h5>
                  {module.studyTopics.map((topic, tIdx) => (
                    <LessonItem 
                      key={tIdx} 
                      title={topic.topic_name} 
                      type="Topic" 
                      isCompleted={false} 
                    />
                  ))}
                </div>
              )}

              {module.quizQuestions && module.quizQuestions.length > 0 && (
                <div>
                  <h5 className="text-[#C08F42] text-[10px] font-bold tracking-[0.2em] mb-4">ASSESSMENTS</h5>
                  {module.quizQuestions.map((quiz, qIdx) => (
                    <LessonItem 
                      key={qIdx} 
                      title={`Quiz Question ${quiz.questionNumber}`} 
                      type="Quiz" 
                      isCompleted={false}
                    />
                  ))}
                </div>
              )}
            </ModuleAccordion>
          ))}

          {/* Stats Footer */}
          <footer className="mt-12 pt-8 border-t border-white/5 flex flex-wrap justify-between gap-8 text-center">
            {stats.map((stat, i) => (
              <div key={i} className="flex-1 min-w-[120px]">
                <div className="text-2xl font-bold text-[#C08F42]">
                  {stat.value}
                </div>
                <div className="text-[13px] font-medium text-zinc-500 mt-2 tracking-widest">
                  {stat.label}
                </div>
              </div>
            ))}
          </footer>
        </section>
      </div>
    </div>
  );
}

"use client"
import { Eye, Trash2, AlertCircle, Loader } from 'lucide-react';
import { useRouter } from 'next/navigation';
import { useGetTeacherPublishedCoursesQuery, useRemoveTeacherMutation } from '@/lib/feature/courses/coursesApi';
import { useState } from 'react';
import ConfirmModal from '@/components/ui/ConfirmModal';
import { toast } from 'sonner';

const CourseCard = ({
    id,
    title,
    grade,
    description,
    studentCount,
    moduleCount,
    onDelete
}: {
    id: string;
    title: string;
    grade: string;
    description: string;
    studentCount: number;
    moduleCount: number;
    onDelete: (id: string, title: string) => void;
}) => {
    const router = useRouter();
    return (
        <div className="relative flex flex-col w-full max-w-[480px] min-h-[260px] p-6 bg-[#121212] border border-white/10 rounded-xl transition-all hover:border-white/20">
            {/* Student Count - Top Right */}
            <div className="absolute top-4 right-6 text-zinc-400 text-sm font-light">
                {studentCount} students
            </div>

            {/* Title */}
            <h2 className="mt-8 text-xl font-semibold text-zinc-100 tracking-tight">
                {title}
            </h2>

            {/* Grade Level */}
            <p className="mt-2 text-[#C08F42] font-medium text-sm">
                Grade {grade}
            </p>

            {/* Description */}
            <p className="mt-4 text-zinc-400 leading-relaxed text-[15px] grow line-clamp-3">
                {description}
            </p>

            {/* Footer: Module Count and Delete Action */}
            <div className="mt-6 flex justify-between items-end">
                <span className="text-zinc-500 text-sm font-light">
                    {moduleCount} modules
                </span>
                <div className='flex gap-2'>
                    <button
                        onClick={() => router.push(`/teacher/courses/${id}`)}
                        className="p-2 cursor-pointer text-zinc-400 hover:text-zinc-100 transition-colors bg-white/5 rounded-lg border border-white/5"
                        aria-label="View course"
                    >
                        <Eye size={20} />
                    </button>

                    <button
                        onClick={() => onDelete(id, title)}
                        className="p-2 cursor-pointer text-red-500/80 hover:text-red-500 transition-colors bg-white/5 rounded-lg border border-white/5"
                        aria-label="Delete course"
                    >
                        <Trash2 size={20} />
                    </button>
                </div>
            </div>
        </div>
    );
};

export default function TeacherCourseList() {
    const { data, isLoading: itemsLoading, error } = useGetTeacherPublishedCoursesQuery();
    const [removeTeacher, { isLoading: isRemoving }] = useRemoveTeacherMutation();
    
    const [selectedCourse, setSelectedCourse] = useState<{ id: string; title: string } | null>(null);

    const handleDelete = async () => {
        if (!selectedCourse) return;

        try {
            await removeTeacher(selectedCourse.id).unwrap();
            toast.success(`You have been removed from "${selectedCourse.title}" successfully.`);
            setSelectedCourse(null);
        } catch (err: any) {
            toast.error(err?.data?.message || "Failed to remove course. Please try again.");
        }
    };

    if (itemsLoading) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[400px] w-full gap-4">
                <Loader className="w-10 h-10 text-[#C08F42] animate-spin" />
                <p className="text-zinc-400 animate-pulse">Loading your courses...</p>
            </div>
        );
    }

    if (error) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[400px] w-full gap-4 p-10">
                <div className="bg-red-500/10 border border-red-500/20 p-6 rounded-xl flex flex-col items-center gap-3 max-w-md text-center">
                    <AlertCircle className="w-12 h-12 text-red-500" />
                    <h3 className="text-zinc-100 font-semibold text-lg">Failed to load courses</h3>
                    <p className="text-zinc-400 text-sm">
                        {(error as any)?.data?.message || "Something went wrong while fetching your courses. Please try again later."}
                    </p>
                </div>
            </div>
        );
    }

    const courses = data?.data || [];

    return (
        <div className="p-10">
            <div className="mb-10">
                <h2 className="text-3xl font-bold text-zinc-100 tracking-tight">Your Courses</h2>
                <p className="text-zinc-400 mt-2">View your assigned curriculum and course structures</p>
            </div>
            
            <main className="flex gap-6 flex-wrap">
                {courses.length > 0 ? (
                    courses.map((course) => (
                        <CourseCard 
                            key={course.id} 
                            id={course.id}
                            title={course.courseName}
                            grade={course.targetGradeLevel}
                            description={course.description || course.generatedCourseName}
                            studentCount={course.class?.totalStudents || 0}
                            moduleCount={course.totalModules}
                            onDelete={(id, title) => setSelectedCourse({ id, title })}
                        />
                    ))
                ) : (
                    <div className="w-full py-20 flex flex-col items-center justify-center border border-dashed border-white/10 rounded-2xl">
                        <p className="text-zinc-500">No published courses found.</p>
                    </div>
                )}
            </main>

            <ConfirmModal 
                open={!!selectedCourse}
                onClose={() => setSelectedCourse(null)}
                onConfirm={handleDelete}
                loading={isRemoving}
                title="Remove from Course"
                description={`Are you sure you want to remove yourself from "${selectedCourse?.title}"? This will unassign you as the teacher for this course.`}
                confirmText="Remove Me"
                variant="delete"
            />
        </div>
    );
}

