const ClassCard = ({ item, index, onStart, isStarting }: { item: Course, index: number, onStart: (id: string) => void, isStarting: boolean }) => {
    return (
        <div className="bg-[#181818] border border-white/10 rounded-2xl p-6 hover:border-[#C08F42]/30 transition-all group">
