"use client";

import { useEffect, useState, useRef } from "react";
import { useRouter } from "next/navigation";
import { Check, Loader2, ArrowRight, Sparkles, BookOpen, Brain, Target, Layers } from "lucide-react";
import { useSetupCourseMutation, coursesApi } from "@/lib/feature/courses/coursesApi";
import { toast } from "sonner";
import { useDispatch } from "react-redux";
import { AppDispatch } from "@/lib/redux/store";
import { CustomSwitch } from "@/components/ui/custom-switch";

const steps = [
    { label: "Analyzing subject & grade level", icon: <Brain className="w-4 h-4" /> },
    { label: "Creating syllabus structure", icon: <Layers className="w-4 h-4" /> },
    { label: "Structuring modules & lessons", icon: <BookOpen className="w-4 h-4" /> },
    { label: "Designing assessments & mastery rules", icon: <Target className="w-4 h-4" /> },
];

const findIdInfo = (obj: any): { realId: string | null; sessionId: string | null } => {
    let realId: string | null = null;
    let sessionId: string | null = null;

    if (!obj || typeof obj !== "object") return { realId: null, sessionId: null };

    const isMongoId = (val: any) => typeof val === "string" && /^[0-9a-fA-F]{24}$/.test(val) && !val.startsWith("SES-") && !val.startsWith("USR-");

    sessionId = obj.unique_session_id || obj.uniqueSessionId || null;
    realId = isMongoId(obj.id) ? obj.id : (isMongoId(obj._id) ? obj._id : null);

    if (!realId || !sessionId) {
        for (const key in obj) {
            const val = obj[key];
            if (!realId && isMongoId(val)) realId = val;
            if (!sessionId && (key === "unique_session_id" || key === "uniqueSessionId")) sessionId = val;

            if (val && typeof val === "object" && (!realId || !sessionId)) {
                const nested = findIdInfo(val);
                if (!realId) realId = nested.realId;
                if (!sessionId) sessionId = nested.sessionId;
            }
        }
    }
    return { realId, sessionId };
};

export default function AiGenerator() {
    const router = useRouter();
    const dispatch = useDispatch<AppDispatch>();
    const [isGenerating, setIsGenerating] = useState(false);

    const generatingRef = useRef(false);

    const [activeSection, setActiveSection] = useState<"basics" | "config">("basics");
    const [mounted, setMounted] = useState(false);

    // Form state for live preview
    const [courseName, setCourseName] = useState("English 101");
    const [subject, setSubject] = useState("English");
    const [targetGradeLevel, setTargetGradeLevel] = useState("69831735070d76578856f2b6");
    const [courseLength, setCourseLength] = useState<"semester" | "full">("full");
    const [semesterCount, setSemesterCount] = useState(1);
    const [quizzesPerModule, setQuizzesPerModule] = useState(5);
    const [masteryReq, setMasteryReq] = useState(70);
    const [totalModules, setTotalModules] = useState(5);
    const [retestingCount, setRetestingCount] = useState(1);
    const [totalQuizQuestions, setTotalQuizQuestions] = useState(25);
    const [estimatedDuration, setEstimatedDuration] = useState(60);

    // Initial defaults flag to prevent effects from clearing user edits
    const hasManuallyEdited = useRef(false);

    // Update defaults based on course length - ONLY on actual change
    useEffect(() => {
        if (courseLength === "semester") {
            setCourseName("Introduction to Physics");
            setSubject("Physics");
            setTargetGradeLevel("69831735070d76578856f2b6");
            setSemesterCount(1);
            setQuizzesPerModule(5);
            setMasteryReq(70);
            setTotalModules(5);
            setRetestingCount(1);
            setTotalQuizQuestions(25);
            setEstimatedDuration(60);
            setDiagnosticTest(false);
            setRetestingAllowed(true);
        } else {
            setCourseName("Advanced Mathematics");
            setSubject("Mathematics");
            setTargetGradeLevel("69831632106883775a56936e");
            setSemesterCount(2);
            setQuizzesPerModule(5);
            setMasteryReq(80);
            setTotalModules(10);
            setRetestingCount(2);
            setTotalQuizQuestions(50);
            setEstimatedDuration(45);
            setDiagnosticTest(true);
            setRetestingAllowed(true);
        }
    }, [courseLength]);

    const [diagnosticTest, setDiagnosticTest] = useState(false);
    const [retestingAllowed, setRetestingAllowed] = useState(true);
    const [midtermExam, setMidtermExam] = useState(true);
    const [finalExam, setFinalExam] = useState(true);

    const [setupCourse, { isLoading }] = useSetupCourseMutation();

    useEffect(() => setMounted(true), []);

    // Generation Progress/Overlay State
    const [generationStep, setGenerationStep] = useState(0);
    const [progress, setProgress] = useState(0);

    const handleGenerate = async () => {
        if (isGenerating || generatingRef.current) return;

        const payload = {
            course_name: courseName,
            subject: subject,
            target_grade_level: targetGradeLevel,
            course_length: courseLength === "semester" ? "6 Months" : "1 Year",
            semester_count: courseLength === "semester" ? 1 : (semesterCount || 2),
            diagnostic_test_before_course: diagnosticTest,
            retesting_allowed: retestingAllowed,
            retesting_count: retestingCount,
            quizzes_per_module: quizzesPerModule,
            midterm_examination: midtermExam,
            final_examination: finalExam,
            total_quiz_questions: totalQuizQuestions,
            mastery_requirement: masteryReq,
            total_modules: totalModules,
            estimated_duration_min_per_class: estimatedDuration
        };

        setIsGenerating(true);
        generatingRef.current = true;
        setGenerationStep(0);
        setProgress(0);

        let currentProgress = 0;
        const interval = setInterval(() => {
            let increment = 1;
            if (currentProgress < 30) increment = 2;
            else if (currentProgress > 70) increment = 0.5;
            else if (currentProgress > 90) increment = 0.1;

            currentProgress = Math.min(currentProgress + increment, 95);
            setProgress(Math.floor(currentProgress));

            if (currentProgress > 25 && currentProgress < 50) setGenerationStep(1);
            else if (currentProgress >= 50 && currentProgress < 75) setGenerationStep(2);
            else if (currentProgress >= 75) setGenerationStep(3);
        }, 150);

        try {
            const res = await setupCourse(payload).unwrap();
            const { realId, sessionId } = findIdInfo(res);

            let finalId = realId;
            if (!finalId && sessionId) {
                try {
                    const allCoursesRes = await dispatch(coursesApi.endpoints.getAllCourses.initiate()).unwrap();
                    const matchedCourse = allCoursesRes.data?.find((c: any) =>
                        c.uniqueSessionId === sessionId || c.unique_session_id === sessionId
                    );
                    if (matchedCourse?.id) finalId = matchedCourse.id;
                } catch (discoveryErr) {
                    // Fallback discovery failed
                }
            }

            clearInterval(interval);
            setProgress(100);
            setGenerationStep(3);

            setTimeout(() => {
                if (finalId) {
                    toast.success("AI Content Generated & Drafted!", {
                        duration: 10000,
                        action: {
                            label: "Publish Course",
                            onClick: () => router.push(`/admin/courses/${finalId}/publish`),
                        },
                    });
                    // Redirect directly to the publish page
                    router.push(`/admin/courses/${finalId}/publish`);
                } else {
                    toast.error("Course metadata sync failed. Please refresh the page.");
                }
                setIsGenerating(false);
                generatingRef.current = false;

            }, 600);
        } catch (error: any) {
            setIsGenerating(false);
            generatingRef.current = false;
            clearInterval(interval);

            let errorMessage = "Failed to generate course content.";
            if (error?.status === 502 || error?.status === 504) {
                errorMessage = "AI Server Busy: The AI is taking too long to write the syllabus. Please try again.";
            } else if (error?.status === 409) {
                errorMessage = "This course configuration already exists.";
            } else if (error?.data?.message) {
                errorMessage = error.data.message;
            }
            toast.error(errorMessage);
        }
    };

    return (
        <div className={`min-h-screen text-white relative transition-opacity duration-500 ${mounted ? "opacity-100" : "opacity-0"}`}>
