                        </div>
                        <div>
                            <h1 className="text-2xl font-bold text-white">AI Course Builder</h1>
                            <p className="text-gray-400 text-sm">Build your course with AI-powered generation</p>
                        </div>
                    </div>
                </div>

                {/* Section Tabs (Mobile) */}
                <div className="flex lg:hidden gap-2 mb-6">
                    <button
