                                        />
                                    </div>

                                    <div className="space-y-2 mb-4">
                                        <label className="text-xs font-bold text-gray-300">ESTIMATED DURATION (min per class)</label>
                                        <input
                                            type="number"
                                            value={estimatedDuration}
                                            onChange={(e) => setEstimatedDuration(parseInt(e.target.value) || 0)}
                                            className="w-full bg-[#1a1a1a] border border-gray-700 rounded-lg p-3 text-sm text-white focus:outline-none focus:border-[#D0AD6B] focus:ring-1 focus:ring-[#D0AD6B]/20 transition-all"
                                        />
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Live Preview Summary */}
                        <div className="mt-4 bg-[#121212] border border-gray-800 rounded-xl p-5 hover:border-gray-700 transition-all duration-300">
                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-3">Live Preview</h3>
                            <div className="grid grid-cols-3 gap-4">
                                <div className="text-center p-3 bg-[#1a1a1a] rounded-lg">
                                    <p className="text-[#D0AD6B] text-xl font-bold">{totalModules}</p>
                                    <p className="text-gray-500 text-[10px] mt-0.5">Modules</p>
                                </div>
                                <div className="text-center p-3 bg-[#1a1a1a] rounded-lg">
                                    <p className="text-[#D0AD6B] text-xl font-bold">{quizzesPerModule * totalModules}</p>
