                        <div className="space-y-3 mb-8">
                            {steps.map((step, index) => (
                                <div key={index} className={`flex items-center gap-4 p-3 rounded-lg transition-all duration-300 ${index <= generationStep ? "bg-[#222]" : ""}`}>
