        </div>
      </div>
      <div>
        <span className="text-3xl font-bold text-white block mb-1">{value}</span>
        <div className="flex items-center justify-between">
          <span className={`text-xs flex items-center gap-1 ${trendUp ? "text-[#22C55E]" : "text-gray-500"}`}>
