    const teachers = teachersRes?.data || [];

    const [startDate, setStartDate] = useState("");
    const [startTime, setStartTime] = useState("09:00");
    const [endTime, setEndTime] = useState("11:00");
    const [selectedTeacherId, setSelectedTeacherId] = useState<string | null>(null);

    useEffect(() => setMounted(true), []);

    const completionSteps = [
        { label: "Start Date", done: startDate !== "" },
        { label: "Schedule", done: startTime !== "" && endTime !== "" },
        { label: "Teacher", done: selectedTeacherId !== null },
    ];
    const completionPercent = Math.round((completionSteps.filter(s => s.done).length / completionSteps.length) * 100);

    useEffect(() => {
        if (course) {
            setStartDate(course.startDate ? course.startDate.split('T')[0] : "");
            setStartTime(course.startTime || "09:00");
            setEndTime(course.endTime || "11:00");
            setSelectedTeacherId(course.teacherId || null);
        }
    }, [course]);

    const handleRemoveTeacherAction = async () => {
        setSelectedTeacherId(null);
        if (!id) return;
        try {
            await removeTeacher(id).unwrap();
            toast.success("Teacher removed from course");
        } catch (err: any) {
            // Silently fail teacher remove
        }
    };

    const handlePublish = async () => {
        if (!id) {
            toast.error("No course ID provided");
            return;
        }

        try {
            await updateCourse({
                id: id as string,
                courseName: course?.courseName,
                subject: course?.subject,
                description: course?.description || "Updated course details",
                isPublished: true,
                startDate: startDate ? new Date(startDate).toISOString() : new Date().toISOString(),
                startTime,
                endTime,
                teacherId: selectedTeacherId || undefined
            }).unwrap();

            setShowSuccess(true);
            setTimeout(() => router.push("/admin/courses"), 1500);
        } catch (error: any) {
            toast.error(error?.data?.message || "Failed to publish course");
        }
    };

    return (
        <div className={`min-h-screen text-white p-4 md:p-8 pb-24 transition-opacity duration-500 ${mounted ? "opacity-100" : "opacity-0"}`}>
            <div className="max-w-7xl space-y-6">

                {/* Header */}
                <div className="bg-[#121212] border border-gray-800 rounded-xl p-6 hover:border-gray-700 transition-all">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-[#D4AF37]/10 rounded-lg">
                                <Sparkles className="w-5 h-5 text-[#D4AF37]" />
                            </div>
                            <div>
                                <h1 className="text-[#d4b57e] font-bold text-lg uppercase tracking-wider">Publish Course</h1>
                                <p className="text-gray-400 text-sm">Finalize settings and make English available to students</p>
                            </div>
                        </div>
                        {/* Completion indicator */}
                        <div className="hidden md:flex items-center gap-3">
                            <div className="text-right">
                                <p className="text-xs text-gray-500">Readiness</p>
                                <p className="text-[#D4AF37] font-bold">{completionPercent}%</p>
                            </div>
                            <div className="w-12 h-12 rounded-full border-2 border-[#D4AF37]/30 flex items-center justify-center relative">
                                <svg className="w-12 h-12 -rotate-90 absolute" viewBox="0 0 36 36">
                                    <circle cx="18" cy="18" r="15" fill="none" stroke="#333" strokeWidth="2" />
                                    <circle cx="18" cy="18" r="15" fill="none" stroke="#D4AF37" strokeWidth="2"
                                        strokeDasharray={`${completionPercent * 0.94} 94`}
                                        strokeLinecap="round"
                                        className="transition-all duration-500"
                                    />
                                </svg>
                                <Eye className="w-4 h-4 text-[#D4AF37] z-10" />
                            </div>
                        </div>
                    </div>

                    {/* Step indicators */}
                    <div className="flex gap-2 mt-4 pt-4 border-t border-gray-800">
                        {completionSteps.map((step, i) => (
                            <div key={i} className="flex-1">
                                <div className={`h-1 rounded-full transition-all duration-500 ${step.done ? "bg-[#D4AF37]" : "bg-[#2a2a2a]"}`} />
                                <p className={`text-[10px] mt-1.5 ${step.done ? "text-[#D4AF37]" : "text-gray-600"}`}>{step.label}</p>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Course Start Date */}
                <div className="bg-[#121212] border border-gray-800 rounded-xl p-6 hover:border-gray-700 transition-all group">
                    <div className="flex items-center gap-2 mb-4">
                        <div className="p-1.5 bg-[#D4AF37]/10 rounded-md group-hover:bg-[#D4AF37]/20 transition-colors">
                            <Calendar className="w-4 h-4 text-[#d4b57e]" />
                        </div>
                        <h2 className="text-[#d4b57e] font-bold text-xs uppercase">Course Start Date</h2>
                    </div>
                    <div className="relative">
                    <input
                        type="date"
                        value={startDate}
                        onChange={(e) => setStartDate(e.target.value)}
                        className="w-full bg-[#1a1a1a] border border-gray-700 rounded-lg p-3 text-sm text-gray-300 focus:outline-none focus:border-[#d4b57e] focus:ring-1 focus:ring-[#d4b57e]/20 placeholder-gray-500 transition-all"
                        placeholder="mm/dd/yyyy"
                    />
                </div>
                    <p className="text-gray-500 text-[10px] mt-2">Students will gain access to course materials on this date</p>
                </div>

                {/* Course Schedule */}
                <div className="bg-[#121212] border border-gray-800 rounded-xl p-6 hover:border-gray-700 transition-all group">
                    <div className="flex items-center gap-2 mb-4">
                        <div className="p-1.5 bg-[#D4AF37]/10 rounded-md group-hover:bg-[#D4AF37]/20 transition-colors">
                            <Clock className="w-4 h-4 text-[#d4b57e]" />
                        </div>
                        <h2 className="text-[#d4b57e] font-bold text-xs uppercase">Course Schedule</h2>
                        {startTime && endTime && (
                            <span className="ml-auto text-xs text-gray-500 bg-[#1a1a1a] px-2 py-1 rounded-md">
                                Duration: {(() => {
                                    const [sh, sm] = startTime.split(":").map(Number);
                                    const [eh, em] = endTime.split(":").map(Number);
                                    const diff = (eh * 60 + em) - (sh * 60 + sm);
                                    return diff > 0 ? `${Math.floor(diff / 60)}h ${diff % 60}m` : "—";
                                })()}
                            </span>
                        )}
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="text-[10px] text-gray-500 block mb-1.5">Start Time</label>
                            <input
                                type="time"
                                value={startTime}
                                onChange={(e) => setStartTime(e.target.value)}
                                className="w-full bg-[#1a1a1a] border border-gray-700 rounded-lg p-3 text-sm text-gray-300 focus:outline-none focus:border-[#d4b57e] focus:ring-1 focus:ring-[#d4b57e]/20 transition-all"
                            />
                        </div>
                        <div>
                            <label className="text-[10px] text-gray-500 block mb-1.5">End Time</label>
                            <input
                                type="time"
                                value={endTime}
                                onChange={(e) => setEndTime(e.target.value)}
                                className="w-full bg-[#1a1a1a] border border-gray-700 rounded-lg p-3 text-sm text-gray-300 focus:outline-none focus:border-[#d4b57e] focus:ring-1 focus:ring-[#d4b57e]/20 transition-all"
                            />
                        </div>
                    </div>
                </div>


                {/* Assign Teacher */}
                <div className="bg-[#121212] border border-gray-800 rounded-xl p-6 hover:border-gray-700 transition-all group">
                    <div className="flex items-center gap-2 mb-4">
                        <div className="p-1.5 bg-[#D4AF37]/10 rounded-md group-hover:bg-[#D4AF37]/20 transition-colors">
                            <User className="w-4 h-4 text-[#d4b57e]" />
                        </div>
                        <h2 className="text-[#d4b57e] font-bold text-xs uppercase">Assign Teacher</h2>
                    </div>

                    {!selectedTeacherId ? (
                        <div className="space-y-4">
                            <Select onValueChange={setSelectedTeacherId} value={selectedTeacherId || ""}>
                                <SelectTrigger className="w-full bg-[#1a1a1a] border-gray-700 text-gray-300 focus:ring-[#D4AF37]/20 focus:border-[#D4AF37]">
                                    <SelectValue placeholder="Select a teacher..." />
                                </SelectTrigger>
                                <SelectContent className="bg-[#1a1a1a] border-gray-800 text-gray-300">
                                    {teachers.map((t: any) => (
                                        <SelectItem key={t.id} value={t.id} className="hover:bg-primary/10 focus:bg-primary/10">
                                            <div className="flex items-center gap-2">
                                                <div className="w-6 h-6 rounded-full overflow-hidden bg-[#D4AF37]/10 border border-[#D4AF37]/20 flex items-center justify-center">
                                                    {t.avatar ? (
                                                        <img src={t.avatar} alt="" className="w-full h-full object-cover" />
                                                    ) : (
                                                        <span className="text-[10px] font-bold text-[#D4AF37] uppercase">{t.name?.[0] || t.email?.[0] || "T"}</span>
                                                    )}
                                                </div>
                                                <span>{t.name} - {t.email}</span>
                                            </div>
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                    ) : (
                        <div className="flex items-center justify-between bg-[#1a1a1a] p-4 rounded-lg border border-[#D4AF37]/20 transition-all">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-[#D4AF37]/10 border border-[#D4AF37]/30 flex items-center justify-center flex-shrink-0 overflow-hidden">
                                    {teachers.find((t: any) => t.id === selectedTeacherId)?.avatar ? (
                                        <img 
                                            src={teachers.find((t: any) => t.id === selectedTeacherId)?.avatar} 
                                            alt="" 
                                            className="w-full h-full object-cover"
                                        />
                                    ) : (
                                        <span className="text-[#D4AF37] text-sm font-bold uppercase select-none">
                                            {teachers.find((t: any) => t.id === selectedTeacherId)?.name?.[0] || teachers.find((t: any) => t.id === selectedTeacherId)?.email?.[0] || "T"}
                                        </span>
                                    )}
                                </div>
                                <div className="min-w-0">
                                    <p className="text-sm font-bold text-gray-200 truncate">
                                        {teachers.find((t: any) => t.id === selectedTeacherId)?.name || teachers.find((t: any) => t.id === selectedTeacherId)?.email || "Teacher Unnamed"}
                                    </p>
                                    <p className="text-xs text-gray-500 truncate">
                                        {teachers.find((t: any) => t.id === selectedTeacherId)?.email}
                                    </p>
                                </div>
                            </div>
                            <button 
                                onClick={handleRemoveTeacherAction} 
                                className="text-red-500 hover:text-red-400 hover:bg-red-500/10 p-2 rounded-lg transition-all disabled:opacity-50"
                                disabled={isRemovingTeacher}
                            >
                                {isRemovingTeacher ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4" />}
                            </button>
                        </div>
                    )}
                </div>

                {/* Notification Settings */}
                <div className="bg-[#121212] border border-gray-800 rounded-xl p-6 flex items-center justify-between hover:border-gray-700 transition-all">
                    <div className="flex flex-col gap-1">
                        <div className="flex items-center gap-2">
                            <div className="p-1.5 bg-[#D4AF37]/10 rounded-md">
                                <Bell className="w-4 h-4 text-[#d4b57e]" />
                            </div>
                            <h2 className="text-[#d4b57e] font-bold text-xs uppercase">Notification Settings</h2>
                        </div>
                        <p className="text-gray-500 text-[10px] ml-9">Email and in-app notifications enabled for course updates</p>
                    </div>
                    <Switch defaultChecked />
                </div>

                {/* Publication Summary */}
                <div className="bg-[#121212] border border-gray-800 rounded-xl p-6 hover:border-gray-700 transition-all">
                    <div className="flex items-center gap-2 mb-6">
                        <BookOpen className="w-4 h-4 text-[#D4AF37]" />
                        <h2 className="text-[#d4b57e] font-bold text-xs uppercase">Publication Summary</h2>
                    </div>
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                        {[
                            { label: "Course", value: course?.courseName || "—", highlight: false },
                            { label: "Duration", value: course?.courseLength || "—", highlight: false },
                            { label: "Schedule", value: `${course?.startTime || "—"} - ${course?.endTime || "—"}`, highlight: false },
                            { 
                                label: "Teacher", 
                                value: teachers.find((t: any) => t.id === selectedTeacherId) 
                                    ? (teachers.find((t: any) => t.id === selectedTeacherId)?.name || teachers.find((t: any) => t.id === selectedTeacherId)?.email) 
                                    : "Not Assigned", 
                                highlight: true 
                            },
                            { label: "Modules", value: String(course?.totalModules || "—"), highlight: true },
                            { label: "Mastery Requirement", value: `${course?.masteryRequirement || "—"}%`, highlight: true },
                        ].map((item, i) => (
                            <div key={i} className="p-3 bg-[#1a1a1a] rounded-lg border border-gray-800 hover:border-gray-700 transition-colors">
                                <label className="text-gray-500 text-[10px] block mb-1">{item.label}</label>
                                <p className={`font-semibold text-sm ${item.highlight ? "text-[#D4AF37]" : "text-white"}`}>{item.value}</p>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="flex justify-end pt-4">
                    <button
                        onClick={handlePublish}
                        disabled={isLoading || course?.isPublished}
                        className="bg-[#d4b57e] hover:bg-[#c4a56e] text-black font-bold py-3.5 px-8 rounded-xl flex items-center gap-2 transition-all disabled:opacity-50 disabled:cursor-not-allowed hover:shadow-lg hover:shadow-[#d4b57e]/20 active:scale-[0.98]"
                    >
                        <span>{isLoading ? "Publishing..." : course?.isPublished ? "Published" : "Publish Course"}</span>
                        {!isLoading && !course?.isPublished && <ArrowRight className="w-5 h-5" />}
                        {course?.isPublished && <CheckCircle className="w-5 h-5" />}
                    </button>
                </div>

            </div>

            {/* Success Overlay */}
            {showSuccess && (
                <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center">
                    <div className="text-center">
                        <div className="w-20 h-20 mx-auto mb-4 rounded-full bg-[#22C55E]/20 flex items-center justify-center">
                            <CheckCircle className="w-10 h-10 text-[#22C55E]" />
                        </div>
                        <h2 className="text-2xl font-bold text-white mb-2">Course Published!</h2>
                        <p className="text-gray-400 text-sm">Redirecting to courses...</p>
                    </div>
                </div>
            )}
        </div>
    );
}

function Switch({ defaultChecked = false }: { defaultChecked?: boolean }) {
    const [checked, setChecked] = useState(defaultChecked);
    return (
        <button
            onClick={() => setChecked(!checked)}
            className={`w-12 h-6 rounded-full p-1 transition-all duration-200 ease-in-out focus:outline-none ${checked ? 'bg-[#d4b57e] shadow-lg shadow-[#d4b57e]/20' : 'bg-gray-700'}`}
        >
            <div
                className={`bg-black w-4 h-4 rounded-full shadow-md transform transition-transform duration-200 ease-in-out ${checked ? 'translate-x-6' : 'translate-x-0'}`}
            />
        </button>
    );
}

"use client";

import { Button } from "@/components/ui/button";
import { Trash2, BookOpen, Users, BarChart3, Clock, Sparkles } from "lucide-react";
import Link from "next/link";
import { useGetAllCoursesQuery, useUpdateCourseMutation, useDeleteCourseMutation } from "@/lib/feature/courses/coursesApi";
import { Loader2 } from "lucide-react";
import { toast } from "sonner";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { useState } from "react";

export default function Courses() {
    const { data: response, isLoading, error } = useGetAllCoursesQuery();
    const [updateCourse, { isLoading: isUpdating }] = useUpdateCourseMutation();
    const [deleteCourse, { isLoading: isDeleting }] = useDeleteCourseMutation();
    const courses = response?.data || [];
    
    const [courseToDelete, setCourseToDelete] = useState<string | null>(null);
    const [publishingId, setPublishingId] = useState<string | null>(null);

    const handleConfirmDelete = async () => {
        if (!courseToDelete) return;
        
        try {
            await deleteCourse(courseToDelete).unwrap();
            toast.success("Course deleted successfully!");
        } catch (err: any) {
            toast.error(err?.data?.message || "Failed to delete course");
        } finally {
            setCourseToDelete(null);
        }
    }

    const handlePublish = async (course: any) => {
        setPublishingId(course.id);
        try {
            await updateCourse({
                id: course.id,
                courseName: course.courseName,
                subject: course.subject,
                description: course.description || "Synthesized by AI",
                isPublished: true,
                startDate: course.startDate || "2026-04-01T00:00:00.000Z",
                startTime: course.startTime || "09:00 AM",
                endTime: course.endTime || "11:00 AM",
                teacherId: course.teacherId || "6983160b106883775a56936a"
            }).unwrap();
            toast.success("Course published successfully!");
        } catch (err: any) {
            toast.error(err?.data?.message || "Failed to publish course");
        } finally {
            setPublishingId(null);
        }
    };

    const getStatusStyles = (status: boolean) => {
        if (status) return "bg-[#22C55E]/10 text-[#22C55E] border-[#22C55E]/20";
        return "bg-[#D4AF37]/10 text-[#D4AF37] border-[#D4AF37]/20";
    };

    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
                <Loader2 className="w-10 h-10 text-[#D4AF37] animate-spin" />
                <p className="text-gray-400 animate-pulse">Fetching your courses...</p>
            </div>
        );
    }

    if (error) {
        return (
            <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-8 text-center">
                <p className="text-red-500 font-medium mb-2">Failed to load courses</p>
                <p className="text-red-400 text-sm">Please check your connection and try again.</p>
            </div>
        );
    }

    return (
        <div className="p-4 md:p-0">
            {/* Header Section */}
            <div className="bg-card shadow-[0_4px_4px_0] border shadow-primary/20 rounded-xl p-6 md:p-8 mb-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <p className="text-[#D4AF37] text-xs font-medium tracking-wider uppercase mb-1">Curriculum</p>
                    <h2 className="text-primary text-xl md:text-2xl font-semibold mb-1">Your Courses</h2>
                    <p className="text-secondary text-xs md:text-sm">
                        {courses.length} courses • {courses.filter(c => c.isPublished).length} active
                    </p>
                </div>
                <div className="flex gap-3 w-full md:w-auto">
                    <Link href="/admin/ai-generator" className="flex-1 md:flex-none">
                        <button className="w-full flex items-center justify-center gap-2 bg-transparent border border-[#D4AF37]/30 text-[#D4AF37] px-5 py-2 rounded-2xl text-sm font-medium cursor-pointer hover:bg-[#D4AF37]/10 transition-all">
                            <Sparkles className="w-4 h-4" />
                            AI Generate
                        </button>
                    </Link>
                    <Link href="/admin/courses/config" className="flex-1 md:flex-none">
                        <button className="w-full bg-primary text-black px-6 py-2 rounded-2xl text-base font-normal cursor-pointer hover:shadow-lg hover:shadow-primary/20 transition-all">
                            Configure
                        </button>
                    </Link>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
                {courses.map((course, idx) => (
                    <div
                        key={course.id}
                        className="bg-card shadow-[0_4px_4px_0] border shadow-primary/20 rounded-xl p-5 md:p-6 flex flex-col h-full min-h-62.5 group hover:border-[#D4AF37]/30 transition-all duration-300"
                        style={{ animationDelay: `${idx * 100}ms` }}
                    >
                        <div className="flex justify-between items-center mb-4">
                            <span className={`px-3 md:px-4 py-1 rounded-full text-[10px] md:text-xs font-medium border ${getStatusStyles(course.isPublished)}`}>
                                {course.isPublished && <span className="inline-block w-1.5 h-1.5 rounded-full bg-[#22C55E] mr-1.5 animate-pulse" />}
                                {course.isPublished ? "Active" : "Draft"}
                            </span>
                            <button
                                onClick={() => setCourseToDelete(course.id)}
                                className="text-destructive hover:bg-destructive/10 p-1.5 rounded-lg active:scale-90 transition-all cursor-pointer"
                            >
                                <Trash2 size={18} strokeWidth={1.5} />
                            </button>
                        </div>

                        <div className="mb-4">
                            <h3 className="text-foreground text-base md:text-xl font-semibold mb-1 group-hover:text-[#D4AF37] transition-colors line-clamp-1">{course.courseName}</h3>
                            <p className="text-primary text-sm font-medium mb-2">{course.class?.gradeLevel || course.targetGradeLevel}</p>
                            <p className="text-secondary text-sm font-normal leading-relaxed line-clamp-2 italic">
                                {course.generatedCourseName}
                            </p>
                        </div>

                        <div className="mb-4">
                            <div className="flex justify-between text-xs mb-1.5">
                                <span className="text-gray-400">Course Progress</span>
                                <span className="text-white font-medium">0%</span>
                            </div>
                            <div className="h-1.5 w-full bg-[#2D2D2D] rounded-full overflow-hidden">
                                <div
                                    className="h-full bg-gradient-to-r from-[#D4AF37] to-[#F59E0B] rounded-full transition-all duration-1000 ease-out"
                                    style={{ width: `0%` }}
                                />
                            </div>
                        </div>

                        <div className="flex flex-wrap items-center gap-4 mb-4 mt-auto">
                            <div className="flex items-center gap-1.5 text-secondary text-xs font-normal">
                                <BookOpen size={14} className="text-[#D4AF37]" /> {course.totalModules} modules
                            </div>
                            <div className="flex items-center gap-1.5 text-secondary text-xs font-normal">
                                <Users size={14} className="text-[#D4AF37]" /> {course.class?.totalStudents || 0} students
                            </div>
                            <div className="flex items-center gap-1.5 text-secondary text-xs font-normal">
                                <Clock size={14} className="text-[#D4AF37]" /> {course.estimatedDurationMinPerClass} min/class
                            </div>
                            <div className="flex items-center gap-1.5 text-secondary text-xs font-normal">
                                <BarChart3 size={14} className="text-[#D4AF37]" /> {course.masteryRequirement}% Mastery
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-3 mt-2">
                            <Button
                                onClick={() => !course.isPublished && handlePublish(course)}
                                disabled={isUpdating || course.isPublished}
                                className="h-auto bg-primary text-black py-2 md:py-2.5 rounded-2xl text-sm font-medium active:scale-95 transition-all cursor-pointer hover:bg-primary/90 hover:shadow-lg hover:shadow-primary/20 disabled:opacity-50"
                            >
                                {isUpdating && publishingId === course.id ? <Loader2 className="w-4 h-4 animate-spin" /> : course.isPublished ? "Published" : "Publish"}
                            </Button>

                            <Button
                                asChild
                                variant="outline"
                                className="h-auto border-foreground/20 text-foreground py-2 md:py-2.5 rounded-2xl text-sm font-medium hover:text-primary hover:border-primary/30 hover:bg-transparent active:scale-95 transition-all cursor-pointer"
                            >
                                <Link href={`/admin/courses/${course.id}`}>
                                    View
                                </Link>
                            </Button>
                        </div>
                    </div>
                ))}

                {courses.length === 0 && (
                    <div className="col-span-full py-20 flex flex-col items-center justify-center bg-card rounded-xl border border-dashed border-gray-700">
                        <BookOpen className="w-12 h-12 text-gray-600 mb-4" />
                        <p className="text-secondary text-center font-medium">No courses available yet.</p>
                        <p className="text-gray-500 text-sm mt-1">Start by generating a course with AI.</p>
                    </div>
                )}
            </div>

            <AlertDialog open={!!courseToDelete} onOpenChange={() => setCourseToDelete(null)}>
                <AlertDialogContent className="bg-card border shadow-xl">
                    <AlertDialogHeader>
                        <AlertDialogTitle className="text-primary">Are you absolutely sure?</AlertDialogTitle>
                        <AlertDialogDescription className="text-secondary">
                            This action cannot be undone. This will permanently delete the course
                            and remove all associated data from our servers.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel className="bg-transparent border-primary/20 text-foreground hover:bg-primary/10">Cancel</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleConfirmDelete}
                            className="bg-destructive text-white hover:bg-destructive/90"
                            disabled={isDeleting}
                        >
                            {isDeleting ? <Loader2 className="w-4 h-4 animate-spin" /> : "Delete Course"}
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
}

