                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-[#A0A0A0] text-sm">Total Students</p>
                    <p className="text-3xl font-bold mt-2">{summary?.totalStudents || 0}</p>
                    <p className="text-xs text-[#22C55E] mt-1">Overall enrolled</p>
                  </div>
                  <div className="bg-[#D4AF37]/10 p-3 rounded-lg group-hover:bg-[#D4AF37]/20 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-[#D4AF37]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
                    </svg>
                  </div>
                </div>
              </div>

              <div className="bg-[#1E1E1E] rounded-xl border border-[#2D2D2D] p-6 hover:border-[#00C853]/30 transition-all duration-300 group">
                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-[#A0A0A0] text-sm">Engaged</p>
                    <p className="text-3xl font-bold mt-2 text-[#00C853]">{summary?.engaged || 0}</p>
                    <p className="text-xs text-gray-500 mt-1">Currently active</p>
                  </div>
                  <div className="bg-[#00C853]/10 p-3 rounded-lg group-hover:bg-[#00C853]/20 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-[#00C853]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                    </svg>
                  </div>
                </div>
              </div>

              <div className="bg-[#1E1E1E] rounded-xl border border-[#2D2D2D] p-6 hover:border-[#FF6D00]/30 transition-all duration-300 group">
                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-[#A0A0A0] text-sm">Activity</p>
                    <p className="text-3xl font-bold mt-2 text-[#FF6D00]">{summary?.noActivity || 0}</p>
                    <p className="text-xs text-gray-500 mt-1">No recent activity</p>
                  </div>
                  <div className="bg-[#FF6D00]/10 p-3 rounded-lg group-hover:bg-[#FF6D00]/20 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-[#FF6D00]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  </div>
                </div>
              </div>

              <div className="bg-[#1E1E1E] rounded-xl border border-[#2D2D2D] p-6 hover:border-[#8B5CF6]/30 transition-all duration-300 group">
                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-[#A0A0A0] text-sm">Avg. Attendance</p>
                    <p className="text-3xl font-bold mt-2">{summary?.attendanceRate || 0}%</p>
                    <div className="h-1.5 w-24 bg-[#2D2D2D] rounded-full mt-2 overflow-hidden">
                      <div className="h-full bg-[#8B5CF6] rounded-full" style={{ width: `${summary?.attendanceRate || 0}%` }} />
                    </div>
                  </div>
                  <div className="bg-[#8B5CF6]/10 p-3 rounded-lg group-hover:bg-[#8B5CF6]/20 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-[#8B5CF6]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  </div>
                </div>
              </div>
            </div>

            {/* Students Table */}
            <div className="bg-[#1E1E1E] rounded-xl border border-[#2D2D2D] overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="border-b border-[#2D2D2D]">
                      <th className="text-left py-4 px-6 text-[#A0A0A0] font-normal">
                        Student Name
                      </th>
                      <th className="text-left py-4 px-6 text-[#A0A0A0] font-normal">
                        Student ID
                      </th>
                      <th 
                        className="text-left py-4 px-6 text-[#A0A0A0] font-normal cursor-pointer hover:text-white transition-colors"
                        onClick={() => {
                          if (sortBy === 'class') {
                            setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
                          } else {
                            setSortBy('class');
                            setSortOrder('asc');
                          }
                        }}
                      >
                        <div className="flex items-center gap-1">
                          Class
                          <svg xmlns="http://www.w3.org/2000/svg" className={`h-4 w-4 transform transition-transform ${sortBy === 'class' ? (sortOrder === 'desc' ? 'rotate-180' : '') : 'opacity-0 group-hover:opacity-100'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                          </svg>
                        </div>
                      </th>
                      <th className="text-left py-4 px-6 text-[#A0A0A0] font-normal">
                        Mastery
                      </th>
                      <th className="text-left py-4 px-6 text-[#A0A0A0] font-normal">
                        Attendance
                      </th>
                      <th className="text-left py-4 px-6 text-[#A0A0A0] font-normal">
                        Action
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    {isLoading ? (
                      <tr>
                        <td colSpan={6} className="py-20 text-center">
                          <Loader2 className="w-8 h-8 animate-spin mx-auto text-[#D4AF37]" />
                          <p className="text-gray-400 mt-2">Loading students...</p>
                        </td>
                      </tr>
                    ) : students.length > 0 ? (
                      students.map((student, idx) => (
                        <tr
                          key={student.id}
                          className="border-b border-[#2D2D2D] hover:bg-[#1a1a1a] transition-all duration-200 group"
                          style={{ animationDelay: `${idx * 50}ms` }}
                        >
                          <td className="py-4 px-6">
                            <div className="flex items-center gap-3">
                              {student.profilePicture ? (
                                <div className="w-9 h-9 rounded-full overflow-hidden shrink-0">
                                  <img src={student.profilePicture} alt={student.name} className="w-full h-full object-cover" />
                                </div>
                              ) : (
                                <div className="w-9 h-9 rounded-full bg-[#D4AF37]/10 flex items-center justify-center text-[#D4AF37] text-sm font-bold shrink-0">
                                  {student.name.split(' ').map(n => n[0]).join('')}
                                </div>
                              )}
                              <p className="font-medium group-hover:text-[#D4AF37] transition-colors">{student.name}</p>
                            </div>
                          </td>
                          <td className="py-4 px-6 text-gray-400 font-mono text-sm">{student.studentId}</td>
                          <td className="py-4 px-6">
                            <span className="px-2.5 py-1 bg-[#2D2D2D] rounded-lg text-xs font-medium">{student.class}</span>
                          </td>
                          <td className="py-4 px-6">
                            <div className="flex items-center gap-2">
                              <div className="h-1.5 w-16 bg-[#2D2D2D] rounded-full overflow-hidden">
                                <div className={`h-full rounded-full transition-all duration-500 ${getMasteryBg(student.mastery)}`} style={{ width: `${student.mastery}%` }} />
                              </div>
                              <span className={`font-semibold text-sm ${getMasteryColor(student.mastery)}`}>{student.mastery}%</span>
                            </div>
                          </td>
                          <td className="py-4 px-6">
                            <span className="text-sm font-medium">N/A</span>
                          </td>
                          <td className="py-4 px-6">
                            <button
                              onClick={() => handleViewClick(student as any)}
                              className="p-2 rounded-lg text-[#A0A0A0] hover:text-[#D4AF37] hover:bg-[#D4AF37]/10 transition-all cursor-pointer"
                            >
                              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" className="w-5 h-5">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                              </svg>
                            </button>
                          </td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td colSpan={6} className="py-20 text-center text-gray-500">
                          No students found.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>

              {/* Pagination */}
              {totalPages > 1 && (
                <div className="flex items-center justify-center py-6 border-t border-[#2D2D2D]">
                  <nav className="flex items-center space-x-2">
                    <button
                      onClick={() =>
                        setCurrentPage((prev) => Math.max(prev - 1, 1))
                      }
                      disabled={currentPage === 1}
                      className="w-10 h-10 rounded-lg bg-[#2D2D2D] hover:bg-[#3A3A3A] transition-colors disabled:opacity-50"
                    >
                      <svg
                        xmlns="http://www.w3.org/2000/svg"
                        className="h-5 w-5 mx-auto"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M15 19l-7-7 7-7"
                        />
                      </svg>
                    </button>

                    {Array.from({ length: totalPages }, (_, i) => i + 1).map(
                      (page) => (
                        <button
                          key={page}
                          onClick={() => setCurrentPage(page)}
                          className={`w-10 h-10 rounded-lg transition-colors ${currentPage === page
                            ? "bg-[#D4AF37] text-black"
                            : "bg-[#2D2D2D] hover:bg-[#3A3A3A]"
                            }`}
                        >
                          {page}
                        </button>
                      ),
                    )}

                    <button
                      onClick={() =>
                        setCurrentPage((prev) => Math.min(prev + 1, totalPages))
                      }
                      disabled={currentPage === totalPages}
                      className="w-10 h-10 rounded-lg bg-[#2D2D2D] hover:bg-[#3A3A3A] transition-colors disabled:opacity-50"
                    >
                      <svg
                        xmlns="http://www.w3.org/2000/svg"
                        className="h-5 w-5 mx-auto"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M9 5l7 7-7 7"
                        />
                      </svg>
                    </button>
                  </nav>
                </div>
              )}
            </div>
          </>
        ) : (
          // Student Detail View
          <div className="bg-[#1E1E1E] rounded-xl border border-[#2D2D2D] overflow-hidden">
            {/* Header */}
            <div className="p-6 border-b border-[#2D2D2D] flex flex-col md:flex-row md:items-center justify-between">
              <div className="flex items-center gap-4 mb-4 md:mb-0">
                <button
                  onClick={handleBackToList}
                  className="text-[#A0A0A0] hover:text-white transition-colors"
                  aria-label="Back to student list"
                >
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    className="h-6 w-6"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M10 19l-7-7m0 0l7-7m-7 7h18"
                    />
                  </svg>
                </button>
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 rounded-full bg-[#2D2D2D] flex items-center justify-center overflow-hidden">
                    {selectedStudent?.profilePicture ? (
                      <img src={selectedStudent.profilePicture} alt={selectedStudent.name} className="w-full h-full object-cover" />
                    ) : (
                      <span className="text-xl font-bold text-[#D4AF37]">
                        {selectedStudent?.name.split(' ').map(n => n[0]).join('')}
                      </span>
                    )}
                  </div>
                  <div>
                    <h2 className="text-2xl font-bold">{selectedStudent?.name || studentDetail.name}</h2>
                    <p className="text-[#A0A0A0]">
                      Student ID: {selectedStudent?.studentId || studentDetail.id} • Grade:{" "}
                      {selectedStudent?.class || studentDetail.grade}
                    </p>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="bg-[#2D2D2D] rounded-lg p-4">
                  <p className="text-[#A0A0A0] text-sm">Enrolled Courses</p>
                  <p className="text-2xl font-bold mt-1">
                    {studentDetail.enrolledCourses}
                  </p>
                </div>
                <div className="bg-[#2D2D2D] rounded-lg p-4">
                  <p className="text-[#A0A0A0] text-sm">Avg Progress</p>
                  <p className="text-2xl font-bold mt-1 text-[#D4AF37]">
                    {studentDetail.avgProgress}
                  </p>
                </div>
                <div className="bg-[#2D2D2D] rounded-lg p-4">
                  <p className="text-[#A0A0A0] text-sm">Avg Mastery</p>
                  <p className="text-2xl font-bold mt-1 text-[#D4AF37]">
                    {studentDetail.avgMastery}
                  </p>
                </div>
                <div className="bg-[#2D2D2D] rounded-lg p-4">
                  <p className="text-[#A0A0A0] text-sm">Attendance Rate</p>
                  <p className="text-2xl font-bold mt-1 text-[#D4AF37]">
                    {studentDetail.attendanceRate}
                  </p>
                </div>
              </div>
            </div>

            {/* Tabs */}
            <div className="p-6 border-b border-[#2D2D2D]">
              <div className="flex border-b border-[#2D2D2D]">
                <button
                  onClick={() => handleTabChange("overview")}
                  className={`pb-3 px-4 font-medium text-sm ${isActiveTab("overview")
                    ? "text-[#D4AF37] border-b-2 border-[#D4AF37]"
                    : "text-[#A0A0A0] hover:text-white"
                    }`}
                >
                  Overview
                </button>
                <button
                  onClick={() => handleTabChange("quiz-history")}
                  className={`pb-3 px-4 font-medium text-sm ${isActiveTab("quiz-history")
                    ? "text-[#D4AF37] border-b-2 border-[#D4AF37]"
                    : "text-[#A0A0A0] hover:text-white"
                    }`}
                >
                  Quiz History
                </button>
              </div>
            </div>

            {/* Tab Content */}
            <div className="p-6">
              {isActiveTab("overview") ? (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  {/* Left Column - Enrolled Courses */}
                  <div className="lg:col-span-1">
                    <h3 className="text-lg font-bold mb-4">Enrolled Courses</h3>
                    <div className="space-y-4">
                      {studentDetail.courses.map((course) => (
                        <div
                          key={course.name}
                          className="bg-[#2D2D2D] rounded-lg p-4"
                        >
                          <div className="flex justify-between items-start mb-2">
                            <h4 className="font-medium">{course.name}</h4>
                            <span className="text-[#D4AF37] font-medium">
                              {course.mastery}
                            </span>
                          </div>
                          <div className="w-full bg-[#3A3A3A] rounded-full h-2.5">
                            <div
                              className="bg-[#D4AF37] h-2.5 rounded-full"
                              style={{
                                width: `${course.completion.replace("%", "")}%`,
                              }}
                            ></div>
                          </div>
                          <p className="text-[#A0A0A0] text-sm mt-1">
                            {course.completion} complete
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* Right Column - Course Progress */}
                  <div className="lg:col-span-2">
                    <div className="bg-[#2D2D2D] rounded-lg p-6">
                      <div className="flex justify-between items-start mb-4">
                        <h3 className="text-lg font-bold">Mathematics</h3>
                        <div>
                          <span className="text-[#D4AF37] font-medium">
                            {studentDetail.courses[0].mastery}
                          </span>
                          <span className="text-[#A0A0A0] text-sm ml-1">
                            mastery
                          </span>
                          <span className="text-[#A0A0A0] text-sm mx-1">•</span>
                          <span className="text-[#D4AF37] font-medium">
                            {studentDetail.courses[0].completion}
                          </span>
                          <span className="text-[#A0A0A0] text-sm ml-1">
                            complete
                          </span>
                        </div>
                      </div>

                      <div className="border-b border-[#3A3A3A] pb-4 mb-4">
                        <div className="flex space-x-2 mb-2">
                          <button
                            onClick={() => handleTabChange("overview")}
                            className="px-3 py-1 rounded-full text-sm font-medium bg-[#D4AF37] text-black"
                          >
                            Overview
                          </button>
                          <button
                            onClick={() => handleTabChange("quiz-history")}
                            className="px-3 py-1 rounded-full text-sm font-medium bg-[#2D2D2D] text-[#A0A0A0]"
                          >
                            Quiz History
                          </button>
                        </div>
                      </div>

                      <div className="mb-4">
                        <h4 className="font-medium mb-2">Course Progress</h4>
                        <div className="flex justify-between text-sm mb-1">
                          <span>Module Completed</span>
                          <span>6/12</span>
                        </div>
                        <div className="w-full bg-[#3A3A3A] rounded-full h-2.5">
                          <div
                            className="bg-[#D4AF37] h-2.5 rounded-full"
                            style={{ width: "50%" }}
                          ></div>
                        </div>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <h4 className="font-medium mb-1">Current Lesson</h4>
                          <p className="text-[#A0A0A0]">
                            Linear Equations: Introduction
                          </p>
                        </div>
                        <div>
                          <h4 className="font-medium mb-1">Latest Quiz</h4>
                          <p className="text-[#A0A0A0]">2 attempts</p>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              ) : (
                // Quiz History Tab
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  {/* Left Column - Enrolled Courses */}
                  <div className="lg:col-span-1">
                    <h3 className="text-lg font-bold mb-4">Enrolled Courses</h3>
                    <div className="space-y-4">
                      {studentDetail.courses.map((course) => (
                        <div
                          key={course.name}
                          className="bg-[#2D2D2D] rounded-lg p-4"
                        >
                          <div className="flex justify-between items-start mb-2">
                            <h4 className="font-medium">{course.name}</h4>
                            <span className="text-[#D4AF37] font-medium">
                              {course.mastery}
                            </span>
                          </div>
                          <div className="w-full bg-[#3A3A3A] rounded-full h-2.5">
                            <div
                              className="bg-[#D4AF37] h-2.5 rounded-full"
                              style={{
                                width: `${course.completion.replace("%", "")}%`,
                              }}
                            ></div>
                          </div>
                          <p className="text-[#A0A0A0] text-sm mt-1">
                            {course.completion} complete
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* Right Column - Quiz History */}
                  <div className="lg:col-span-2">
                    <div className="bg-[#2D2D2D] rounded-lg p-6">
                      <h3 className="text-lg font-bold mb-4">Mathematics</h3>
                      <div className="text-sm mb-4">
                        <span className="text-[#D4AF37] font-medium">
                          {studentDetail.courses[0].mastery}
                        </span>
                        <span className="text-[#A0A0A0] text-sm mx-1">
                          mastery
                        </span>
                        <span className="text-[#A0A0A0] text-sm mx-1">•</span>
                        <span className="text-[#D4AF37] font-medium">
                          {studentDetail.courses[0].completion}
                        </span>
                        <span className="text-[#A0A0A0] text-sm mx-1">
                          complete
                        </span>
                      </div>

                      <div className="border-b border-[#3A3A3A] pb-4 mb-4">
                        <div className="flex space-x-2">
                          <button
                            className={`px-3 py-1 rounded-full text-sm font-medium ${isActiveTab("overview")
                              ? "bg-[#D4AF37] text-black"
                              : "bg-[#2D2D2D] text-[#A0A0A0]"
                              }`}
                            onClick={() => handleTabChange("overview")}
                          >
                            Overview
                          </button>
                          <button
                            className={`px-3 py-1 rounded-full text-sm font-medium ${isActiveTab("quiz-history")
                              ? "bg-[#D4AF37] text-black"
                              : "bg-[#2D2D2D] text-[#A0A0A0]"
                              }`}
                            onClick={() => handleTabChange("quiz-history")}
                          >
                            Quiz History
                          </button>
                        </div>
                      </div>

                      <div className="space-y-3">
                        {studentDetail.courses[0].modules.map((module) => (
                          <div
                            key={module.id}
                            className="p-4 bg-[#1E1E1E] rounded-lg hover:bg-[#252525] transition-colors"
                          >
                            <div className="flex justify-between items-start">
                              <h4 className="font-medium">{module.name}</h4>
                              <span className="text-[#D4AF37] font-medium">
                                {module.mastery}
                              </span>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

// Type definitions
interface Student {
  id: string;
  name: string;
  studentId: string;
  class: string;
  mastery: number;
  profilePicture?: string;
  attendance?: string;
  enrolledCourses?: number;
  avgProgress?: string;
  avgMastery?: string;
}

interface Module {
  id: string;
  name: string;
  mastery: string;
}

interface Course {
  name: string;
  mastery: string;
  completion: string;
  modules: Module[];
}

interface StudentDetail {
  id: string;
  name: string;
  grade: string;
  enrolledCourses: number;
  avgProgress: string;
  avgMastery: string;
  attendanceRate: string;
