"use client";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { useGetMeQuery } from "@/lib/feature/auth/authApi";
import { useGetAllCoursesQuery } from "@/lib/feature/courses/coursesApi";
import { Bell } from "lucide-react";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { useRouter } from "next/navigation";
import { useMemo, useState, useEffect } from "react";

export function DashboardHeader() {
  const router = useRouter();
  const { data: userData, isLoading } = useGetMeQuery();
  const { data: coursesData } = useGetAllCoursesQuery(undefined, {
    skip: isLoading || !userData?.data || userData.data.role !== "ADMIN",
  });

  const user = userData?.data;

  const [readNotifications, setReadNotifications] = useState<string[]>([]);
  useEffect(() => {
    const stored = localStorage.getItem("read_notifications");
    if (stored) {
      try {
        setReadNotifications(JSON.parse(stored));
      } catch (e) { }
    }
  }, []);

  const unreadCourses = useMemo(() => {
    // Filter to show only unpublished AND UNREAD notifications
    return coursesData?.data?.filter((c) => !c.isPublished && !readNotifications.includes(c.id)).slice(0, 5) || [];
  }, [coursesData, readNotifications]);

  const hasUnread = unreadCourses.length > 0;

  const handleMarkAsRead = (courseId: string) => {
    if (!readNotifications.includes(courseId)) {
      const newRead = [...readNotifications, courseId];
      setReadNotifications(newRead);
      localStorage.setItem("read_notifications", JSON.stringify(newRead));
    }
  };

  const fullName = user ? `${user.firstName} ${user.lastName}` : "Admin";
  const initials = user ? `${user.firstName.charAt(0)}${user.lastName.charAt(0)}`.toUpperCase() : "A";

  if (isLoading) {
    return (
      <header className="bg-[#1A1A1A] border-b border-gray-800 px-4 sm:px-6 lg:px-8 py-6">
        <div className="flex animate-pulse items-center justify-between">
          <div className="h-8 w-48 bg-gray-700 rounded ml-16" />
          <div className="flex items-center gap-3">
            <div className="h-8 w-8 bg-gray-700 rounded-full" />
            <div className="h-4 w-24 bg-gray-700 rounded" />
          </div>
        </div>
      </header>
    );
  }

  return (
    <header className="bg-[#1A1A1A] border-b border-gray-800 px-4 sm:px-6 lg:px-8 py-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        {/* Left: Greeting + Date/Time */}
        <div className="flex-1">
          <h1 className="text-2xl font-bold ml-16 text-white">
            Welcome back, <span className="text-[#D0AD6B]">{user?.firstName || "Admin"}!</span>
          </h1>
        </div>

        {/* Right: Notifications + Avatar */}
        <div className="flex items-center gap-4">

          {user?.role === "ADMIN" && (
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <button className="relative p-2 rounded-full bg-gray-800 hover:bg-gray-700 transition-colors">
                  <Bell className="w-5 h-5 text-gray-300" />
                  {hasUnread && (
                    <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 bg-red-500 rounded-full border border-[#1A1A1A] text-[10px] font-bold flex items-center justify-center text-white">
                      {unreadCourses.length}
                    </span>
                  )}
                </button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-80 bg-[#1A1A1A] border-gray-800 text-white">
                <div className="p-3 border-b border-gray-800">
                  <h3 className="font-semibold text-[#D0AD6B]">Notifications</h3>
                </div>
                <div className="max-h-[300px] overflow-y-auto">
                  {unreadCourses.length > 0 ? (
                    unreadCourses.map((course) => {
                      return (
                        <DropdownMenuItem
                          key={course.id}
                          className="flex flex-col items-start p-3 border-b border-gray-800/50 cursor-pointer focus:bg-[#D0AD6B]/10 transition-colors bg-[#D0AD6B]/5 hover:bg-[#D0AD6B]/10 border-l-2 border-l-[#D0AD6B]"
                          onClick={() => {
                            handleMarkAsRead(course.id);
                            router.push(`/admin/courses/${course.id}/publish`);
                          }}
                        >
                          <div className="flex justify-between w-full items-center mb-1">
                            <p className="font-semibold text-sm line-clamp-1 text-[#D0AD6B]">
                              {course.courseName || course.subject} Generated!
                            </p>
                            <span className="w-2 h-2 rounded-full bg-[#D0AD6B] flex-shrink-0"></span>
                          </div>
                          <p className="text-xs mt-1 line-clamp-2 text-gray-400">
                            This course has been successfully generated by AI. Click to publish.
                          </p>
                        </DropdownMenuItem>
                      );
                    })
                  ) : (
                    <div className="p-4 text-center text-gray-500 text-sm">
                      No new notifications
                    </div>
                  )}
                </div>
              </DropdownMenuContent>
            </DropdownMenu>
          )}

          {/* User Avatar + Info */}
          <div className="flex items-center gap-3">
            <Avatar className="h-8 w-8 ring-2 ring-[#314B79] hidden sm:block ring-offset-2">
              <AvatarImage
                src={user?.profilePicture || ""}
                alt={fullName}
                className="object-cover"
              />
              <AvatarFallback className="bg-[#314B79] text-white font-semibold text-lg">
                {initials}
              </AvatarFallback>
            </Avatar>

            <div className="hidden sm:block">
              <p className="text-sm font-semibold text-[#D0AD6B]">{fullName}</p>
              <p className="text-xs font-semibold text-[#D0AD6B]">{user?.role}</p>
            </div>
          </div>
        </div>
      </div>
    </header>
  );
}

"use client";

import {
  BarChart3,
  BookOpen,
  Brain,
  CalendarDays,
  ChevronLeft,
  ChevronRight,
  LayoutDashboard,
  Loader2,
  LogOut,
  Menu,
  Settings,
  User,
  Users,
} from "lucide-react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { useLogoutMutation } from "@/lib/feature/auth/authApi";
import { logout } from "@/lib/slice/user/userSlice";
import { cn } from "@/utils/utils";
import { useDispatch } from "react-redux";
import { toast } from "sonner";
import Logo from "../common/Logo";

// ── Role-specific menu configuration ─────────────────────────────────────
type MenuItem = {
  title: string;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  icon: any;
  href: string;
};

const getMenuItems = (role: "admin" | "teacher" | "student"): MenuItem[] => {
  // Common base (Dashboard is always first)
  const base = [
    {
      title: "Dashboard",
      icon: LayoutDashboard,
      href: `/${role}/dashboard`,
    },
  ];

  if (role === "admin") {
    return [
      ...base,
      { title: "Courses", icon: BookOpen, href: "/admin/courses" },
      { title: "AI Generator", icon: Brain, href: "/admin/ai-generator" },
      { title: "Students", icon: Users, href: "/admin/students" },
      { title: "Settings", icon: Settings, href: "/admin/settings" },
    ];
  }

  if (role === "teacher") {
    return [
      ...base,
      { title: "My Courses", icon: BookOpen, href: "/teacher/courses" }, // or /teacher/my-courses
      { title: "Students", icon: Users, href: "/teacher/students" },
      { title: "Profile", icon: User, href: "/teacher/profile" },
    ];
  }

  // Student default
  return [
    ...base,
    { title: "My Courses", icon: BookOpen, href: "/student/courses" },
    { title: "Progress", icon: BarChart3, href: "/student/progress" },
    { title: "Attendance", icon: CalendarDays, href: "/student/attendance" },
    { title: "Profile", icon: User, href: "/student/profile" },
  ];
};

interface DashboardSidebarProps {
  role: "admin" | "teacher" | "student" | string; // fallback to string for safety, but ideally should be one of the three
}

export function DashboardSidebar({ role }: DashboardSidebarProps) {
  const dispatch = useDispatch();
  const pathname = usePathname();
  const [collapsed, setCollapsed] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [logoutApi, { isLoading: isLoggingOut }] = useLogoutMutation();

  const menuItems = getMenuItems(role as "admin" | "teacher" | "student");

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 1024) {
        setCollapsed(true);
      } else {
        setCollapsed(false);
        setMobileMenuOpen(false);
      }
    };

    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const handleLogout = async () => {
    try {
      const response = await logoutApi().unwrap();
      if (response.success) {
        dispatch(logout());
        setMobileMenuOpen(false);
        toast.success(response.message || "Logged out successfully!");
        window.location.href = "/login";
      }
    } catch (error: any) {
      console.error("Logout failed:", error);
      toast.error(error?.data?.message || "Failed to log out");
    }
  };

  const sidebarContent = (
    <>
      {/* Logo & Toggle */}
      <div className="flex items-center justify-between p-4 bg-[#1A1A1A]">
        {!collapsed && (
          <Link href="/" className="flex items-center">
            <Logo />
          </Link>
        )}
        <Button
          variant="ghost"
          size="icon"
          onClick={() =>
            window.innerWidth >= 1024
              ? setCollapsed(!collapsed)
              : setMobileMenuOpen(false)
          }
          className="h-9 w-9 text-[#D0AD6B]"
        >
          {collapsed ? (
            <ChevronRight className="h-5 w-5" />
          ) : (
            <ChevronLeft className="h-5 w-5" />
          )}
        </Button>
      </div>

      {/* Navigation */}
      <nav className="flex-1 py-6 px-4 bg-[#1A1A1A]">
        <ul className="space-y-2">
          {menuItems.map((item) => {
            const isActive = pathname === item.href;
            const Icon = item.icon;

            return (
              <li key={item.href}>
                <Link
                  href={item.href}
                  onClick={() => setMobileMenuOpen(false)}
                  className={cn(
                    "flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all duration-200 group relative",
                    isActive
                      ? "bg-[#D0AD6B] text-gray-900 shadow-md"
                      : "text-[#D0AD6B] hover:bg-gray-800/50 hover:text-white",
                    collapsed && "justify-center px-3",
                  )}
                >
                  <Icon
                    className={cn(
                      "h-5 w-5 flex-shrink-0",
                      isActive && "text-gray-900",
                    )}
                  />
                  {!collapsed && (
                    <span className="text-base">{item.title}</span>
                  )}

                  {/* Tooltip on collapse */}
                  {collapsed && (
                    <span className="absolute left-full ml-3 px-3 py-2 bg-gray-900 text-white text-sm rounded-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all whitespace-nowrap z-50 shadow-lg">
                      {item.title}
                    </span>
                  )}
                </Link>
              </li>
            );
          })}
        </ul>
      </nav>

      {/* Logout */}
      <div className="p-4 border-t bg-[#1A1A1A] border-gray-800">
        <Button
          onClick={handleLogout}
          disabled={isLoggingOut}
          variant="ghost"
          className={cn(
            "w-full justify-center cursor-pointer gap-3 text-red-500 hover:text-red-400 hover:bg-red-950/30 text-sm font-medium",
            collapsed && "justify-center px-3",
          )}
        >
          {isLoggingOut ? (
            <Loader2 className="h-5 w-5 animate-spin" />
          ) : (
            <LogOut className="h-5 w-5" />
          )}
          {!collapsed && (
            <span>{isLoggingOut ? "Logging out..." : "Log out"}</span>
          )}
        </Button>
      </div>
    </>
  );

  return (
    <>
      {/* Mobile Hamburger */}
      <Button
        onClick={() => setMobileMenuOpen(true)}
        className="fixed top-4 left-4 z-50 lg:hidden bg-[#1A1A1A] p-3 rounded-lg hover:bg-gray-800 transition"
      >
        <Menu className="h-6 w-6 text-[#D0AD6B]" />
      </Button>

      {/* Sidebar */}
      <aside
        className={cn(
          "fixed inset-y-0 left-0 z-40 flex flex-col shadow-lg transition-all duration-300 lg:relative lg:translate-x-0 bg-[#0f0f0f]",
          collapsed ? "w-20" : "w-72",
          mobileMenuOpen
            ? "translate-x-0"
            : "-translate-x-full lg:translate-x-0",
        )}
      >
        {sidebarContent}
      </aside>

      {/* Mobile overlay */}
      {mobileMenuOpen && (
        <div
          className="fixed inset-0 bg-black/60 z-30 lg:hidden"
          onClick={() => setMobileMenuOpen(false)}
        />
      )}
    </>
  );
}

"use client";
import { ChevronRight, Copy, User, Mail, Shield, Camera, Lock, UserCheck, AlertCircle, Save } from "lucide-react";
import Image from "next/image";
import { useRef, useState, ChangeEvent, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import avatarDefault from "/public/assets/avatar.png";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import ConfirmModal from "@/components/ui/ConfirmModal";
import { useRouter } from "next/navigation";

const profileSchema = z.object({
    firstName: z.string().min(2, "First name is too short"),
    lastName: z.string().min(2, "Last name is too short"),
    email: z.string().email("Invalid email address"),
    currentPassword: z.string().optional(),
    newPassword: z.string().min(8, "Password must be at least 8 characters").optional().or(z.literal('')),
    confirmPassword: z.string().optional().or(z.literal('')),
}).refine((data) => data.newPassword === data.confirmPassword, {
    message: "Passwords don't match",
    path: ["confirmPassword"],
});

type ProfileFormValues = z.infer<typeof profileSchema>;

export default function StudentEditProfile() {
    const fileInputRef = useRef<HTMLInputElement>(null);
    const router = useRouter();
    const [selectedImage, setSelectedImage] = useState<string | null>(null);
    const [imageFile, setImageFile] = useState<File | null>(null);
    const [mounted, setMounted] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [showConfirmModal, setShowConfirmModal] = useState(false);
    const [pendingData, setPendingData] = useState<ProfileFormValues | null>(null);

    useEffect(() => setMounted(true), []);

    const {
        register,
        handleSubmit,
        formState: { errors },
    } = useForm<ProfileFormValues>({
        resolver: zodResolver(profileSchema),
        defaultValues: {
            firstName: "Alex",
            lastName: "Johnson",
            email: "alexjohnson@gmail.com",
        }
    });

    const handleImageChange = (e: ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            setImageFile(file);
            const imageUrl = URL.createObjectURL(file);
            setSelectedImage(imageUrl);
            toast.info("New photo selected! Don't forget to save.", {
                style: { backgroundColor: '#1a1a1a', border: '1px solid #D4AF37', color: '#D4AF37' }
            });
        }
    };

    const onSubmit = (formData: ProfileFormValues) => {
        setPendingData(formData);
        setShowConfirmModal(true);
    };

    const confirmUpdate = () => {
        if (!pendingData) return;
        setIsLoading(true);
        setShowConfirmModal(false);
        
        // Simulate API call
        setTimeout(() => {
            const finalData = { ...pendingData, profilePhoto: imageFile };
            console.log("Submit Data:", finalData);
            setIsLoading(false);
            toast.success("Profile updated successfully!", {
                icon: <UserCheck className="w-5 h-5 text-green-500" />,
                style: { backgroundColor: '#1a1a1a', border: '1px solid #22C55E' }
            });
            setPendingData(null);
        }, 1500);
    };

    const handleCopyId = (userId: string): void => {
        navigator.clipboard.writeText(userId);
        toast.success("User ID copied to clipboard");
    };

    return (
        <>
            <form onSubmit={handleSubmit(onSubmit)} className={`space-y-8 transition-all duration-700 ${mounted ? "opacity-100 translate-y-0" : "opacity-0 translate-y-4"}`}>

                {/* Header / Intro Card */}
                <div className="relative overflow-hidden bg-card border rounded-xl shadow-[0_4px_4px_0] shadow-primary/20 p-8 md:p-10">
                    <div className="absolute top-0 right-0 p-10 opacity-[0.03] scale-150 rotate-12">
                        <Shield size={160} className="text-primary" />
                    </div>
                    <div className="relative z-10">
                        <div className="flex items-center gap-3 mb-2">
                            <div className="p-1.5 bg-primary/10 rounded-lg">
                                <UserCheck className="w-5 h-5 text-primary" />
                            </div>
                            <h1 className="text-xl md:text-2xl font-bold text-white">Security & Profile</h1>
                        </div>
                        <p className="text-gray-400 text-sm md:text-base font-normal max-w-2xl">
                            Updating your profile helps us personalize your learning path. Keep your account secure by using a strong password.
                        </p>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                    {/* Left Column: Avatar and Quick Stats */}
                    <div className="lg:col-span-4 space-y-8">
                        <div className="bg-card border rounded-xl shadow-[0_4px_4px_0] shadow-primary/20 p-8 flex flex-col items-center">
                            <div className="relative group mb-6">
                                <div className="relative w-32 h-32 rounded-full overflow-hidden border-4 border-card shadow-2xl transition-all group-hover:scale-105 group-hover:shadow-primary/20">
                                    <Image
                                        src={selectedImage || avatarDefault}
                                        alt="Profile"
                                        fill
                                        className="object-cover"
                                    />
                                    <div 
                                        onClick={() => fileInputRef.current?.click()}
                                        className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex flex-col items-center justify-center transition-opacity cursor-pointer"
                                    >
                                        <Camera className="w-8 h-8 text-white mb-1" />
                                        <span className="text-white text-[10px] font-bold uppercase tracking-widest text-center">Change<br/>Photo</span>
                                    </div>
                                </div>
                                <div className="absolute -bottom-2 -right-2 p-2 bg-primary rounded-full border-4 border-card shadow-xl group-hover:scale-110 transition-transform cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                                    <Camera className="w-4 h-4 text-black" />
                                </div>
                            </div>
                            <input
                                type="file"
                                ref={fileInputRef}
                                hidden
                                accept="image/*"
                                onChange={handleImageChange}
                            />
                            <div className="text-center">
                                <h3 className="text-lg font-bold text-white">Alex Johnson</h3>
                                <p className="text-primary text-xs font-medium uppercase tracking-[0.2em] mt-1">Grade 9 Student</p>
                            </div>
                        </div>

                        <div className="bg-primary/5 border border-primary/20 rounded-xl p-6 relative overflow-hidden group">
                            <div className="absolute -right-4 -bottom-4 opacity-5 group-hover:opacity-10 transition-opacity">
                                <AlertCircle size={80} className="text-primary" />
                            </div>
                            <h4 className="flex items-center gap-2 text-sm font-bold text-primary mb-3">
                                <AlertCircle className="w-4 h-4" />
                                Security Tip
                            </h4>
                            <p className="text-xs text-gray-400 leading-relaxed">
                                Use a unique password you don&apos;t use anywhere else. Enable 2FA in settings for extra safety.
                            </p>
                        </div>
                    </div>

                    {/* Right Column: Fields */}
                    <div className="lg:col-span-8 space-y-8">
                        {/* Basic Info */}
                        <div className="bg-card border rounded-xl shadow-[0_4px_4px_0] shadow-primary/20 p-8">
                            <div className="flex items-center gap-2 mb-8 border-b border-gray-800/50 pb-4">
                                <User className="w-5 h-5 text-gray-400" />
                                <h2 className="text-lg font-bold text-white uppercase tracking-widest text-sm">Personal Information</h2>
                            </div>
                            
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500">First Name</label>
                                    <div className="group relative">
                                        <Input
                                            {...register("firstName")}
                                            className="w-full h-12 rounded-xl px-4 border-gray-800 bg-[#151515] focus:bg-[#1a1a1a] focus:border-primary/50 transition-all text-white placeholder:text-gray-700 shadow-inner"
                                        />
                                        {errors.firstName && <p className="text-red-500 text-xs mt-1.5 flex items-center gap-1"><AlertCircle className="w-3 h-3" /> {errors.firstName.message}</p>}
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500">Last Name</label>
                                    <Input
                                        {...register("lastName")}
                                        className="w-full h-12 rounded-xl px-4 border-gray-800 bg-[#151515] focus:bg-[#1a1a1a] focus:border-primary/50 transition-all text-white shadow-inner"
                                    />
                                    {errors.lastName && <p className="text-red-500 text-xs mt-1.5 flex items-center gap-1"><AlertCircle className="w-3 h-3" /> {errors.lastName.message}</p>}
                                </div>
                                <div className="space-y-2 md:col-span-1">
                                    <label className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500">Email Address</label>
                                    <div className="relative">
                                        <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-600" />
                                        <Input
                                            {...register("email")}
                                            className="w-full h-12 rounded-xl pl-11 pr-4 border-gray-800 bg-[#151515] focus:bg-[#1a1a1a] focus:border-primary/50 transition-all text-white shadow-inner"
                                        />
                                    </div>
                                    {errors.email && <p className="text-red-500 text-xs mt-1.5 flex items-center gap-1"><AlertCircle className="w-3 h-3" /> {errors.email.message}</p>}
                                </div>
                                <div className="space-y-2 md:col-span-1">
                                    <label className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500">Learning ID <span className="text-gray-700">(Managed)</span></label>
                                    <div className="relative">
                                        <Input
                                            defaultValue="@alexjohnson"
                                            disabled
                                            className="w-full h-12 rounded-xl px-4 border-gray-800 bg-[#1a1a1a]/50 text-gray-600 shadow-inner cursor-not-allowed border-dashed"
                                        />
                                        <button
