"use client";

import React, { useState, useEffect, useCallback } from "react";
import { Button } from "@/components/ui/button";
import {
    Clock, ChevronRight, BookOpen, TrendingUp, Target, Award, Calendar, Flame,
    Zap, Star, Bell, CheckCircle, AlertCircle, ArrowUpRight, ArrowDownRight,
    MapPin, Play, X as XIcon
} from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import ConfirmModal from "@/components/ui/ConfirmModal";

/* ─── tiny sparkline component ─── */
function Sparkline({ data, color }: { data: number[]; color: string }) {
    const max = Math.max(...data);
    const min = Math.min(...data);
    const range = max - min || 1;
    const w = 60, h = 20;
    const points = data.map((v, i) => `${(i / (data.length - 1)) * w},${h - ((v - min) / range) * h}`).join(" ");
    return (
        <svg width={w} height={h} className="opacity-40 group-hover:opacity-100 transition-opacity">
            <polyline fill="none" stroke={color} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" points={points} />
        </svg>
    );
}

export default function StudentDashboard() {
    const router = useRouter();
    const [mounted, setMounted] = useState(false);
    const [animatedValues, setAnimatedValues] = useState({ streak: 0, quizzes: 0, score: 0, attendance: 0, progress: 0 });
    const [countdown, setCountdown] = useState({ h: 0, m: 0, s: 0 });
    const [dismissedTasks, setDismissedTasks] = useState<number[]>([]);
    const [isJoining, setIsJoining] = useState(false);
    const [confirmModalOpen, setConfirmModalOpen] = useState(false);
    const [taskToDismiss, setTaskToDismiss] = useState<number | null>(null);
    const [isDismissing, setIsDismissing] = useState(false);

    /* ─── animate counters ─── */
    useEffect(() => {
        setMounted(true);
        const targets = { streak: 12, quizzes: 24, score: 85, attendance: 96, progress: 78 };
        const duration = 1400;
        const start = Date.now();
        const tick = () => {
            const elapsed = Date.now() - start;
            const p = Math.min(elapsed / duration, 1);
            const e = 1 - Math.pow(1 - p, 3);
            setAnimatedValues({
                streak: Math.round(targets.streak * e),
                quizzes: Math.round(targets.quizzes * e),
                score: Math.round(targets.score * e),
                attendance: Math.round(targets.attendance * e),
                progress: Math.round(targets.progress * e),
            });
            if (p < 1) requestAnimationFrame(tick);
        };
        requestAnimationFrame(tick);
    }, []);

    /* ─── live countdown to next class ─── */
    useEffect(() => {
        const targetHour = 9; // Assume next class is at 9 AM
        const tick = () => {
            const now = new Date();
            const target = new Date(now);
            target.setHours(targetHour, 0, 0, 0);
            if (now >= target) target.setDate(target.getDate() + 1);
            const diff = Math.max(0, target.getTime() - now.getTime());
            setCountdown({
                h: Math.floor(diff / 3600000),
                m: Math.floor((diff % 3600000) / 60000),
                s: Math.floor((diff % 60000) / 1000),
            });
        };
        tick();
        const id = setInterval(tick, 1000);
        return () => clearInterval(id);
    }, []);

    /* ─── greeting ─── */
    const hour = new Date().getHours();
    const greeting = hour < 12 ? "Good morning" : hour < 17 ? "Good afternoon" : "Good evening";
    const today = new Date().toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" });

    /* ─── data ─── */
    const quickStats = [
        { label: "Streak", value: `${animatedValues.streak} days`, icon: Flame, color: "#F97316", trend: "+2 this week", spark: [4, 5, 2, 8, 10, 11, 12] },
        { label: "Quizzes", value: animatedValues.quizzes, icon: Target, color: "#D4AF37", trend: "Top 5% student", spark: [15, 18, 19, 21, 23, 24, 24] },
        { label: "Avg Score", value: `${animatedValues.score}%`, icon: Award, color: "#22C55E", trend: "↑ 4% this month", spark: [78, 80, 81, 82, 84, 85, 85] },
        { label: "Attendance", value: `${animatedValues.attendance}%`, icon: Calendar, color: "#3B82F6", trend: "Perfect record", spark: [95, 95, 96, 96, 96, 96, 96] },
    ];

    const nextClass = {
        subject: "Mathematics",
        topic: "Solving Linear Equations",
        time: "9:00 AM - 10:30 AM",
        room: "Room 204",
        isToday: true,
    };

    const pendingTasks = [
        { id: 1, type: "Lesson", title: "Linear Equations Mastery", subject: "Math", urgency: "high", due: "Today" },
        { id: 2, type: "Quiz", title: "Grammar Fundamentals", subject: "English", urgency: "medium", due: "Tomorrow" },
        { id: 3, type: "Lesson", title: "Atomic Structure", subject: "Science", urgency: "low", due: "Friday" },
    ].filter(t => !dismissedTasks.includes(t.id));

    const courses = [
        { id: 1, name: "Mathematics", grade: "Grade 9", completed: 65, mastery: 82, color: "#D4AF37", lessons: 12, total: 18 },
        { id: 2, name: "General Science", grade: "Grade 9", completed: 52, mastery: 75, color: "#22C55E", lessons: 8, total: 15 },
        { id: 3, name: "English Language", grade: "Grade 9", completed: 70, mastery: 85, color: "#3B82F6", lessons: 14, total: 20 },
    ];

    const achievements = [
        { id: 1, title: "Night Owl", desc: "Studied past midnight", date: "Last night", icon: Clock, color: "#A855F7" },
        { id: 2, title: "Quiz Master", desc: "5 perfect scores in a row", date: "2 days ago", icon: Star, color: "#D4AF37" },
    ];

    const initiateDismissTask = useCallback((id: number) => {
        setTaskToDismiss(id);
        setConfirmModalOpen(true);
    }, []);

    const confirmDismissTask = async () => {
        if (taskToDismiss === null) return;
        
        setIsDismissing(true);
        // Simulate API delay
        await new Promise(resolve => setTimeout(resolve, 500));
        
        setDismissedTasks(prev => [...prev, taskToDismiss]);
        toast.info("Task removed from list");
        
        setIsDismissing(false);
        setConfirmModalOpen(false);
        setTaskToDismiss(null);
    };

    const handleJoinSession = () => {
        setIsJoining(true);
        toast.success("Connecting to live session...", {
            description: `Joining ${nextClass.topic} with your instructor.`,
        });
        
        // Simulate connection delay
        setTimeout(() => {
            router.push("/student/courses/1"); // Default to Mathematics course for now
            setIsJoining(false);
        }, 1500);
    };

    return (
        <div className={`space-y-6 transition-opacity duration-500 ${mounted ? "opacity-100" : "opacity-0"}`}>

            {/* ─── WELCOME HEADER ─── */}
            <div className="bg-[#1a1a1a] shadow-[0_4px_4px_0] border border-gray-800 shadow-primary/10 rounded-xl p-6 hover:border-primary/20 transition-all group overflow-hidden relative">
                <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity">
                    <Zap size={140} className="text-primary rotate-12" />
                </div>
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 relative z-10">
                    <div>
                        <h1 className="text-xl md:text-2xl font-bold text-white tracking-tight">{greeting}, Monika! 👋</h1>
                        <p className="text-gray-400 text-sm mt-0.5">{today} · Grade 9</p>
                        <div className="flex items-center gap-4 mt-3">
                            <div className="flex items-center gap-1.5 text-xs text-secondary">
                                <Flame className="w-3.5 h-3.5 text-orange-500 fill-orange-500" />
                                <span>12 day study streak</span>
                            </div>
                            <div className="flex items-center gap-1.5 text-xs text-secondary">
                                <Award className="w-3.5 h-3.5 text-primary" />
                                <span>Ranked #4 in Grade 9</span>
                            </div>
                        </div>
                    </div>
                    <Link href="/student/courses">
                        <Button className="bg-primary hover:bg-primary/80 text-black font-bold px-6 py-3 rounded-xl transition-all hover:shadow-lg hover:shadow-primary/20 active:scale-[0.98] flex items-center gap-2 group/btn">
                            Continue Learning
                            <ChevronRight className="w-4 h-4 group-hover/btn:translate-x-1 transition-transform" />
                        </Button>
                    </Link>
                </div>
            </div>

            {/* ─── STATS GRID ─── */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {quickStats.map((stat, idx) => {
                    const Icon = stat.icon;
                    return (
                        <div
                            key={stat.label}
                            className="bg-card shadow-[0_4px_4px_0] border border-gray-800 shadow-primary/5 rounded-xl p-4 sm:p-5 hover:border-primary/30 transition-all duration-300 group cursor-pointer"
                            style={{ opacity: mounted ? 1 : 0, transform: mounted ? "translateY(0)" : "translateY(12px)", transition: `all 0.4s ${idx * 80}ms` }}
                        >
                            <div className="flex justify-between items-start mb-2">
                                <p className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">{stat.label}</p>
                                <div className="w-8 h-8 rounded-lg flex items-center justify-center group-hover:scale-110 transition-transform" style={{ backgroundColor: `${stat.color}15` }}>
                                    <Icon size={16} style={{ color: stat.color }} />
                                </div>
                            </div>
                            <div className="flex items-end justify-between">
                                <div>
                                    <p className="text-xl md:text-2xl font-bold text-white leading-none">{stat.value}</p>
                                    <p className="text-[10px] text-[#22C55E] font-medium mt-1.5 flex items-center gap-0.5">
                                        <ArrowUpRight className="w-2.5 h-2.5" />
                                        {stat.trend}
                                    </p>
                                </div>
                                <Sparkline data={stat.spark} color={stat.color} />
                            </div>
                        </div>
                    );
                })}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                {/* ─── LEFT: Next Class & Tasks ─── */}
                <div className="lg:col-span-2 space-y-6">

                    {/* Next Class */}
                    <div className="bg-card rounded-xl p-6 border border-gray-800 shadow-primary/5 hover:border-primary/20 transition-all group">
                        <div className="flex items-center justify-between mb-6">
                            <div className="flex items-center gap-3">
                                <div className="p-2.5 bg-primary/10 rounded-xl group-hover:bg-primary/20 transition-colors">
                                    <BookOpen className="w-5 h-5 text-primary" />
                                </div>
                                <div>
                                    <h2 className="font-bold text-white">Upcoming Class</h2>
                                    <p className="text-xs text-gray-500">Live interaction with your teacher</p>
                                </div>
                            </div>
                            <div className="flex flex-col items-end">
                                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Starts In</span>
                                <div className="flex gap-1 font-mono text-sm font-bold text-primary">
                                    <span className="bg-primary/5 px-1.5 py-0.5 rounded">{String(countdown.h).padStart(2, "0")}h</span>
                                    <span>:</span>
                                    <span className="bg-primary/5 px-1.5 py-0.5 rounded">{String(countdown.m).padStart(2, "0")}m</span>
                                    <span>:</span>
                                    <span className="bg-primary/5 px-1.5 py-0.5 rounded">{String(countdown.s).padStart(2, "0")}s</span>
                                </div>
                            </div>
                        </div>

                        <div className="bg-[#1a1a1a] rounded-xl p-5 border border-primary/10 group-hover:border-primary/30 transition-all relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-4">
                                <div className="flex items-center gap-1.5 text-[10px] font-bold text-[#22C55E] bg-[#22C55E]/10 px-2.5 py-1 rounded-full uppercase">
                                    <span className="w-1.5 h-1.5 rounded-full bg-[#22C55E] animate-pulse" />
                                    Today
                                </div>
                            </div>
                            <p className="text-primary text-xs font-bold uppercase tracking-widest mb-1">{nextClass.subject}</p>
                            <h3 className="text-lg md:text-xl font-bold text-white mb-4">{nextClass.topic}</h3>

                            <div className="flex flex-wrap items-center gap-5 text-sm">
                                <div className="flex items-center gap-2 text-gray-400">
                                    <Clock className="w-4 h-4 text-primary" />
                                    <span>{nextClass.time}</span>
                                </div>
                                <div className="flex items-center gap-2 text-gray-400">
                                    <MapPin className="w-4 h-4 text-primary" />
                                    <span>{nextClass.room}</span>
                                </div>
                            </div>

                            <Button 
                                onClick={handleJoinSession}
                                disabled={isJoining}
                                className="mt-6 w-full h-12 bg-white hover:bg-gray-100 text-black font-bold rounded-xl transition-all shadow-xl shadow-black/20 flex items-center justify-center gap-2 group/play disabled:opacity-70"
                            >
                                <div className="w-6 h-6 rounded-full bg-black flex items-center justify-center group-hover/play:scale-110 transition-transform">
                                    {isJoining ? (
                                        <div className="w-3 h-3 border-2 border-white border-t-transparent rounded-full animate-spin" />
                                    ) : (
                                        <Play size={12} className="text-white fill-white ml-0.5" />
                                    )}
                                </div>
                                {isJoining ? "Connecting..." : "Join Session"}
                            </Button>
                        </div>
                    </div>

                    {/* Pending Tasks */}
                    <div className="bg-card rounded-xl p-6 border border-gray-800">
                        <div className="flex items-center justify-between mb-6">
                            <h2 className="font-bold text-white flex items-center gap-2">
                                <Target className="w-5 h-5 text-primary" />
                                Learning Roadmap
                            </h2>
                            <span className="text-[10px] text-primary bg-primary/10 px-2.5 py-1 rounded-full font-bold uppercase tracking-wider">{pendingTasks.length} pending items</span>
                        </div>

                        <div className="space-y-3">
                            {pendingTasks.map((task, idx) => (
                                <div
                                    key={task.id}
                                    className="group flex items-center justify-between p-4 rounded-xl border border-gray-800 hover:border-primary/20 hover:bg-[#1a1100]/10 transition-all cursor-pointer relative"
                                    style={{ opacity: mounted ? 1 : 0, transition: `all 0.4s ${idx * 60 + 200}ms` }}
                                >
                                    <div className="flex items-center gap-4">
                                        <div className={`w-1 h-10 rounded-full ${task.urgency === "high" ? "bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.4)]" : "bg-primary"}`} />
                                        <div>
                                            <div className="flex items-center gap-2 mb-1">
                                                <span className={`text-[9px] font-black px-1.5 py-0.5 rounded-md uppercase tracking-wider ${
                                                    task.type === "Quiz" ? "bg-purple-900/40 text-purple-400" : "bg-primary/20 text-primary"
                                                }`}>
                                                    {task.type}
                                                </span>
                                                <span className="text-[10px] text-gray-500 font-medium">{task.subject} · Due {task.due}</span>
                                            </div>
                                            <p className="text-sm font-bold text-white group-hover:text-primary transition-colors">{task.title}</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-4">
                                        <button
                                            onClick={(e) => { e.stopPropagation(); initiateDismissTask(task.id); }}
                                            className="opacity-0 group-hover:opacity-100 p-2 text-gray-600 hover:text-white transition-all"
                                        >
                                            <XIcon size={14} />
                                        </button>
                                        <ChevronRight className="w-5 h-5 text-gray-700 group-hover:text-primary group-hover:translate-x-1 transition-all" />
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* ─── RIGHT: Master & Achievements ─── */}
                <div className="space-y-6">

                    {/* Detailed Progress */}
                    <div className="bg-card rounded-xl p-6 border border-gray-800 flex flex-col items-center">
                        <h3 className="w-full text-sm font-bold text-gray-300 uppercase tracking-widest mb-8 flex items-center gap-2">
                            <TrendingUp className="w-4 h-4 text-primary" />
                            Academic Mastery
                        </h3>

                        <div className="relative w-44 h-44 mb-8">
                            <svg className="w-full h-full -rotate-90" viewBox="0 0 100 100">
                                <circle cx="50" cy="50" r="44" fill="none" stroke="#222" strokeWidth="8" />
                                <circle
                                    cx="50" cy="50" r="44" fill="none" stroke="url(#primaryGradient)" strokeWidth="8"
                                    strokeDasharray={`${animatedValues.progress * 2.764} 276.4`}
                                    strokeLinecap="round"
                                    className="transition-all duration-1000"
                                />
                                <defs>
                                    <linearGradient id="primaryGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                                        <stop offset="0%" stopColor="#D4AF37" />
                                        <stop offset="100%" stopColor="#F59E0B" />
                                    </linearGradient>
                                </defs>
                            </svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center">
                                <span className="text-4xl font-extrabold text-white">{animatedValues.progress}%</span>
                                <span className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">Mastery</span>
                            </div>
                        </div>

                        <div className="w-full space-y-4">
                            {courses.map(course => (
                                <div key={course.name} className="group cursor-pointer">
                                    <div className="flex justify-between items-center mb-1.5 text-xs">
                                        <span className="text-gray-400 group-hover:text-white transition-colors">{course.name}</span>
                                        <span className="font-bold text-primary">{course.mastery}%</span>
                                    </div>
                                    <div className="h-2 w-full bg-[#222] rounded-full overflow-hidden relative">
                                        <div className="absolute inset-0 bg-white/5 z-0" style={{ width: `${course.mastery}%` }} />
                                        <div
                                            className="h-full rounded-full transition-all duration-1000 z-10"
                                            style={{ width: mounted ? `${course.completed}%` : "0%", backgroundColor: course.color }}
                                        />
                                    </div>
                                    <div className="flex justify-between mt-1 text-[9px] text-gray-600">
                                        <span>{course.lessons}/{course.total} lessons</span>
                                        <span>Goal: 90%</span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Achievements */}
                    <div className="bg-card rounded-xl p-6 border border-gray-800">
                        <h3 className="text-sm font-bold text-gray-300 uppercase tracking-widest mb-6 flex items-center gap-2">
                            <Star className="w-4 h-4 text-primary" />
                            Achievements
                        </h3>
                        <div className="space-y-4">
                            {achievements.map((ach, idx) => {
                                const Icon = ach.icon;
                                return (
                                    <div key={ach.id} className="flex gap-4 group" style={{ opacity: mounted ? 1 : 0, transition: `all 0.4s ${idx * 60 + 500}ms` }}>
                                        <div className="w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 transition-transform group-hover:scale-110" style={{ backgroundColor: `${ach.color}15` }}>
                                            <Icon size={20} style={{ color: ach.color }} />
                                        </div>
                                        <div className="min-w-0">
                                            <h4 className="text-sm font-bold text-white group-hover:text-primary transition-colors">{ach.title}</h4>
                                            <p className="text-xs text-gray-500 truncate">{ach.desc}</p>
                                            <p className="text-[10px] text-gray-600 mt-1 uppercase tracking-tighter">{ach.date}</p>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                        <Button variant="ghost" className="w-full mt-6 text-primary text-xs font-bold hover:bg-primary/5 hover:text-primary">
                            View Showcase →
                        </Button>
                    </div>

                </div>
            </div>
            <ConfirmModal 
                open={confirmModalOpen}
                onClose={() => setConfirmModalOpen(false)}
                onConfirm={confirmDismissTask}
                title="Remove Task?"
                description="Are you sure you want to remove this task from your roadmap? This action cannot be undone."
                confirmText="Remove"
                variant="delete"
                loading={isDismissing}
            />
        </div>
    );
}

